const QUESTIONS = [{"id":"g01","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の都道府県の数はいくつですか？","choices":["43","45","47","49"],"answer":2,"a":"日本は1都1道2府43県、合計47都道府県です。","term":"1学期"},{"id":"g02","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の最北端に位置する都道府県はどこですか？","choices":["青森県","北海道","岩手県","秋田県"],"answer":1,"a":"北海道は日本列島の最も北に位置します。","term":"1学期"},{"id":"g03","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"日本列島を大きく4つの島に分けるとき、北海道、本州、四国と何ですか？","choices":["九州","沖縄本島","佐渡島","対馬"],"answer":0,"a":"4大島は北海道、本州、四国、九州です。","term":"1学期"},{"id":"g04","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の国土を東西・南北に広く連なる島々としてとらえたとき、最も大きな島は何ですか？","choices":["北海道","本州","九州","四国"],"answer":1,"a":"本州は日本最大の島です。","term":"1学期"},{"id":"g05","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"日本の標準時の基準となる東経135度の経線が通る兵庫県の都市はどこですか？","choices":["神戸市","明石市","姫路市","西宮市"],"answer":1,"a":"東経135度の子午線は兵庫県明石市付近を通ります。","term":"1学期"},{"id":"g06","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の都道府県で「道」と呼ばれるのはどこですか？","choices":["北海道","東京都","大阪府","京都府"],"answer":0,"a":"北海道だけが「道」と呼ばれます。","term":"1学期"},{"id":"g07","category":"geography","unit":"人口","difficulty":"basic","q":"人口が特に大都市圏へ集まる現象を何といいますか？","choices":["過疎化","都市化","高齢化","工業化"],"answer":1,"a":"都市化は人口や都市的機能が都市へ集中していく現象です。","term":"1学期"},{"id":"g08","category":"geography","unit":"人口","difficulty":"standard","q":"人口が減少し、地域の活力が低下することが問題となる現象を何といいますか？","choices":["過密化","過疎化","都市化","国際化"],"answer":1,"a":"過疎化は人口が少なくなり、生活や産業の維持が難しくなる現象です。","term":"1学期"},{"id":"g09","category":"geography","unit":"人口","difficulty":"basic","q":"日本で高齢者の割合が増えることを何といいますか？","choices":["少子化","高齢化","過密化","都市化"],"answer":1,"a":"高齢化は人口に占める高齢者の割合が高くなることです。","term":"1学期"},{"id":"g10","category":"geography","unit":"人口","difficulty":"standard","q":"人口が大都市などに集中して過密になる一方、地方では過疎化が進む現象を表す語として適切なのはどれですか？","choices":["人口の地域的な偏り","地形の変化","季節風","海流"],"answer":0,"a":"人口は地域によって分布に大きな違いがあります。","term":"1学期"},{"id":"g11","category":"geography","unit":"産業","difficulty":"basic","q":"第一次産業に含まれるものはどれですか？","choices":["農業","製造業","小売業","情報通信業"],"answer":0,"a":"第一次産業には農業・林業・漁業などが含まれます。","term":"1学期"},{"id":"g12","category":"geography","unit":"産業","difficulty":"basic","q":"第二次産業に含まれるものはどれですか？","choices":["漁業","製造業","小売業","運輸業"],"answer":1,"a":"第二次産業には鉱業・製造業・建設業などが含まれます。","term":"1学期"},{"id":"g13","category":"geography","unit":"産業","difficulty":"basic","q":"第三次産業に含まれるものはどれですか？","choices":["農業","林業","製造業","サービス業"],"answer":3,"a":"第三次産業には商業、金融、運輸、サービスなどが含まれます。","term":"1学期"},{"id":"g14","category":"geography","unit":"産業","difficulty":"standard","q":"大都市周辺で、都市向けに野菜や花などを生産する農業を何といいますか？","choices":["近郊農業","促成栽培","抑制栽培","焼畑農業"],"answer":0,"a":"大都市に近い地域で、新鮮な農産物を都市へ出荷する農業を近郊農業といいます。","term":"1学期"},{"id":"g15","category":"geography","unit":"産業","difficulty":"standard","q":"暖かい地域で、出荷時期を早めるために作物を育てる方法は何ですか？","choices":["抑制栽培","促成栽培","輪作","二期作"],"answer":1,"a":"促成栽培は温室などを利用して生育を早め、出荷時期を早める方法です。","term":"1学期"},{"id":"g16","category":"geography","unit":"産業","difficulty":"standard","q":"涼しい地域などで、出荷時期を遅らせる栽培方法は何ですか？","choices":["促成栽培","抑制栽培","近郊農業","二毛作"],"answer":1,"a":"抑制栽培は出荷時期を遅らせる栽培方法です。","term":"1学期"},{"id":"g17","category":"geography","unit":"産業","difficulty":"basic","q":"日本の工業地帯・工業地域が太平洋側に帯状に分布する地域を何と呼びますか？","choices":["太平洋ベルト","中央高地","日本海ベルト","瀬戸内ベルト"],"answer":0,"a":"太平洋ベルトは関東から九州北部にかけて工業が集積する地域です。","term":"1学期"},{"id":"g18","category":"geography","unit":"産業","difficulty":"standard","q":"原料や製品を大量に船で運ぶのに適している工業立地として重要なのはどこですか？","choices":["海岸部の臨海地域","山間部","高原","内陸の盆地"],"answer":0,"a":"大量輸送が可能な港を利用できる臨海部には工場が立地しやすいです。","term":"1学期"},{"id":"g19","category":"geography","unit":"気候","difficulty":"basic","q":"日本の冬、日本海側で雪が多くなる主な原因となる風は何ですか？","choices":["南東の季節風","北西の季節風","東風","南西の季節風"],"answer":1,"a":"冬は大陸から北西の季節風が吹き、日本海で水蒸気を含んで雪を降らせます。","term":"2学期"},{"id":"g20","category":"geography","unit":"気候","difficulty":"basic","q":"太平洋側の多くの地域で、夏に降水量が増える主な要因の一つは何ですか？","choices":["南東からの湿った空気","乾燥した北西風","寒流だけ","フェーン現象だけ"],"answer":0,"a":"夏は太平洋から湿った空気が流れ込み、降水量が増える地域があります。","term":"2学期"},{"id":"g21","category":"geography","unit":"気候","difficulty":"standard","q":"山を越えて吹き下りる乾燥した暖かい風を何といいますか？","choices":["やませ","フェーン現象","季節風","偏西風"],"answer":1,"a":"フェーン現象では山を越えた空気が乾燥し、気温が上がることがあります。","term":"2学期"},{"id":"g22","category":"geography","unit":"気候","difficulty":"basic","q":"北海道や東北の太平洋側などで、夏に冷たい北東風が吹いて気温が下がることがあります。この風を何といいますか？","choices":["やませ","フェーン","からっ風","季節風"],"answer":0,"a":"やませは北東から吹く冷たく湿った風で、農作物に影響することがあります。","term":"2学期"},{"id":"g23","category":"geography","unit":"気候","difficulty":"standard","q":"瀬戸内の気候の特徴として適切なのはどれですか？","choices":["年間を通じて雨が非常に多い","比較的温暖で降水量が少ない","冬に豪雪が続く","一年中低温である"],"answer":1,"a":"瀬戸内は山地に囲まれ、比較的温暖で降水量が少ない傾向があります。","term":"2学期"},{"id":"g24","category":"geography","unit":"気候","difficulty":"standard","q":"中央高地の気候の特徴として適切なのはどれですか？","choices":["年較差が小さい","降水量が非常に多い","内陸性で年較差が大きい","冬でも高温である"],"answer":2,"a":"中央高地は内陸にあり、海の影響を受けにくいため年較差が大きくなります。","term":"2学期"},{"id":"g25","category":"geography","unit":"自然災害","difficulty":"basic","q":"日本で地震が多い主な理由として適切なのはどれですか？","choices":["複数のプレートの境界に位置するため","砂漠が多いため","偏西風が強いため","河川が少ないため"],"answer":0,"a":"日本周辺には複数のプレートがあり、その境界付近で地震活動が活発です。","term":"2学期"},{"id":"g26","category":"geography","unit":"自然災害","difficulty":"basic","q":"大雨などで川の水があふれ、周辺の土地が水につかる災害を何といいますか？","choices":["洪水","津波","土石流","液状化"],"answer":0,"a":"河川の水があふれることによる災害を洪水といいます。","term":"2学期"},{"id":"g27","category":"geography","unit":"自然災害","difficulty":"basic","q":"地震によって海底が大きく動くなどして発生する大きな海の波を何といいますか？","choices":["高潮","津波","洪水","土砂災害"],"answer":1,"a":"海底の地形変化などによって発生する大きな波が津波です。","term":"2学期"},{"id":"g28","category":"geography","unit":"自然災害","difficulty":"standard","q":"地震の揺れによって、地盤が液体のように振る舞う現象を何といいますか？","choices":["液状化現象","風化","侵食","地盤沈下"],"answer":0,"a":"液状化現象は、地震の揺れで砂地盤などが一時的に液体状になる現象です。","term":"2学期"},{"id":"g29","category":"geography","unit":"地域調査","difficulty":"basic","q":"地図上で実際の距離を縮めた割合を示すものを何といいますか？","choices":["縮尺","方位","等高線","凡例"],"answer":0,"a":"縮尺は地図上の距離と実際の距離の割合を示します。","term":"1学期"},{"id":"g30","category":"geography","unit":"地域調査","difficulty":"standard","q":"同じ高さの地点を結んだ線を地形図で何といいますか？","choices":["等高線","経線","緯線","境界線"],"answer":0,"a":"等高線は標高が同じ地点を結んだ線です。","term":"1学期"},{"id":"g31","category":"geography","unit":"地域調査","difficulty":"basic","q":"東西方向を示す0度の基準となる経線は何と呼ばれますか？","choices":["赤道","本初子午線","北回帰線","日付変更線"],"answer":1,"a":"イギリスのグリニッジを通る0度の経線を本初子午線とします。","term":"1学期"},{"id":"g32","category":"geography","unit":"地域調査","difficulty":"basic","q":"地球を南北に分ける0度の緯線を何といいますか？","choices":["赤道","本初子午線","北回帰線","南回帰線"],"answer":0,"a":"赤道は緯度0度の線です。","term":"1学期"},{"id":"g33","category":"geography","unit":"地域調査","difficulty":"standard","q":"日本の国土面積に対して山地・丘陵地が占める割合は、およそどのくらいですか？","choices":["約1割","約3割","約7割","約9割"],"answer":2,"a":"日本は山地・丘陵地が多く、国土の約4分の3を占めると説明されることが多いです。選択肢では約7割が最も近い値です。","term":"1学期"},{"id":"g34","category":"geography","unit":"地域調査","difficulty":"standard","q":"地形図で土地の起伏を表すために使われる代表的な線は何ですか？","choices":["等高線","緯線","経線","行政界"],"answer":0,"a":"等高線によって土地の高さや斜面の様子を読み取れます。","term":"1学期"},{"id":"g35","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"日本の西端に近い地域に位置する県はどれですか？","choices":["長崎県","栃木県","群馬県","山梨県"],"answer":0,"a":"長崎県には日本の西端に近い地域が含まれます。","term":"1学期"},{"id":"g36","category":"geography","unit":"産業","difficulty":"standard","q":"北海道で大規模な畑作が盛んな地域の一つはどこですか？","choices":["十勝平野","越後平野","濃尾平野","筑紫平野"],"answer":0,"a":"十勝平野では小麦、豆類、てんさいなどの畑作が盛んです。","term":"1学期"},{"id":"g37","category":"geography","unit":"産業","difficulty":"standard","q":"新潟県などで稲作が盛んな平野として知られるのはどこですか？","choices":["越後平野","石狩平野","濃尾平野","宮崎平野"],"answer":0,"a":"越後平野は米作りが盛んな地域として知られています。","term":"1学期"},{"id":"g38","category":"geography","unit":"産業","difficulty":"advanced","q":"促成栽培が特に盛んな地域の一つとして知られる高知平野で、冬でも比較的温暖な理由に関係が深いのはどれですか？","choices":["黒潮の影響などで温暖な気候","流氷の影響","寒流の影響だけ","標高が非常に高いこと"],"answer":0,"a":"高知平野は温暖な気候を利用して促成栽培が行われています。","term":"1学期"},{"id":"g39","category":"geography","unit":"自然災害","difficulty":"advanced","q":"災害による被害を小さくするため、地域で危険箇所や避難場所を確認する地図を何といいますか？","choices":["ハザードマップ","地勢図","人口ピラミッド","路線図"],"answer":0,"a":"ハザードマップは災害リスクや避難情報などを確認するための地図です。","term":"2学期"},{"id":"g40","category":"geography","unit":"人口","difficulty":"advanced","q":"人口ピラミッドで、年齢別・男女別の人口構成を読み取ることができます。何を表す図ですか？","choices":["人口の年齢・男女構成","産業別生産額","降水量の分布","標高の分布"],"answer":0,"a":"人口ピラミッドは年齢階級別・男女別の人口構成を表します。","term":"1学期"},{"id":"h01","category":"history","unit":"江戸時代","difficulty":"basic","q":"1603年に征夷大将軍となり江戸幕府を開いた人物は誰ですか？","choices":["織田信長","豊臣秀吉","徳川家康","徳川吉宗"],"answer":2,"a":"徳川家康は1603年に征夷大将軍となり、江戸幕府を開きました。","term":"2学期"},{"id":"h02","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸幕府が大名を統制するために定めた法令は何ですか？","choices":["武家諸法度","御成敗式目","五箇条の御誓文","大日本帝国憲法"],"answer":0,"a":"武家諸法度は大名統制のための重要な法令です。","term":"2学期"},{"id":"h03","category":"history","unit":"江戸時代","difficulty":"standard","q":"大名が江戸と領地を1年おきに行き来する制度を何といいますか？","choices":["参勤交代","鎖国","楽市楽座","廃藩置県"],"answer":0,"a":"参勤交代は大名を江戸と領地の間で定期的に往復させる制度です。","term":"2学期"},{"id":"h04","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代、キリスト教の禁止や貿易の管理などを目的に海外との交流を制限した政策は何と呼ばれますか？","choices":["鎖国","開国","文明開化","富国強兵"],"answer":0,"a":"江戸幕府は海外との交流を厳しく制限しました。現在の教科書では「鎖国」という語の扱いに注意する場合があります。","term":"2学期"},{"id":"h05","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代に幕府が貿易を認めたオランダ商館が置かれた場所はどこですか？","choices":["長崎の出島","横浜","函館","堺"],"answer":0,"a":"オランダ商館は長崎の出島に置かれました。","term":"2学期"},{"id":"h06","category":"history","unit":"江戸時代","difficulty":"standard","q":"徳川吉宗が行った改革を何といいますか？","choices":["享保の改革","寛政の改革","天保の改革","大化の改新"],"answer":0,"a":"徳川吉宗による享保の改革です。","term":"2学期"},{"id":"h07","category":"history","unit":"江戸時代","difficulty":"standard","q":"松平定信が行った改革を何といいますか？","choices":["享保の改革","寛政の改革","天保の改革","明治維新"],"answer":1,"a":"松平定信による寛政の改革です。","term":"2学期"},{"id":"h08","category":"history","unit":"江戸時代","difficulty":"standard","q":"水野忠邦が行った改革を何といいますか？","choices":["享保の改革","寛政の改革","天保の改革","安政の改革"],"answer":2,"a":"水野忠邦による天保の改革です。","term":"2学期"},{"id":"h09","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代の三大改革の一つで、徳川吉宗が行ったものはどれですか？","choices":["享保の改革","寛政の改革","天保の改革","大政奉還"],"answer":0,"a":"三大改革は享保・寛政・天保の改革です。","term":"2学期"},{"id":"h10","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代に都市で栄えた町人文化を何といいますか？","choices":["元禄文化","国風文化","天平文化","化政文化"],"answer":0,"a":"17世紀後半から18世紀初めに上方を中心に栄えた文化を元禄文化といいます。","term":"2学期"},{"id":"h11","category":"history","unit":"江戸時代","difficulty":"standard","q":"19世紀前半、江戸を中心に栄えた町人文化を何といいますか？","choices":["化政文化","元禄文化","飛鳥文化","天平文化"],"answer":0,"a":"化政文化は19世紀前半に江戸を中心に栄えました。","term":"2学期"},{"id":"h12","category":"history","unit":"江戸時代","difficulty":"basic","q":"『富嶽三十六景』を描いた人物は誰ですか？","choices":["歌川広重","葛飾北斎","喜多川歌麿","近松門左衛門"],"answer":1,"a":"葛飾北斎の代表作が『富嶽三十六景』です。","term":"2学期"},{"id":"h13","category":"history","unit":"江戸時代","difficulty":"basic","q":"『東海道五十三次』で知られる浮世絵師は誰ですか？","choices":["葛飾北斎","歌川広重","本居宣長","杉田玄白"],"answer":1,"a":"歌川広重が『東海道五十三次』を描きました。","term":"2学期"},{"id":"h14","category":"history","unit":"江戸時代","difficulty":"standard","q":"蘭学の発展に関係が深い、オランダ語の医学書を翻訳した本は何ですか？","choices":["解体新書","学問のすゝめ","古事記伝","西洋事情"],"answer":0,"a":"杉田玄白らが翻訳した『解体新書』は蘭学の代表例です。","term":"2学期"},{"id":"h15","category":"history","unit":"江戸時代","difficulty":"standard","q":"『古事記伝』を著した国学者は誰ですか？","choices":["本居宣長","伊能忠敬","緒方洪庵","福沢諭吉"],"answer":0,"a":"本居宣長は国学を大成し、『古事記伝』を著しました。","term":"2学期"},{"id":"h16","category":"history","unit":"江戸時代","difficulty":"standard","q":"全国を測量し、精密な日本地図の作成に取り組んだ人物は誰ですか？","choices":["伊能忠敬","間宮林蔵","本居宣長","高野長英"],"answer":0,"a":"伊能忠敬は全国を測量し、精密な日本地図の作成に取り組みました。","term":"2学期"},{"id":"h17","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代に発達した、米を中心とした流通・経済の中心地として栄えた都市はどこですか？","choices":["大阪","奈良","鎌倉","平泉"],"answer":0,"a":"大阪は「天下の台所」と呼ばれ、米の集散地として栄えました。","term":"2学期"},{"id":"h18","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に大名が領地と江戸を往復することで、交通や宿場町の発達にもつながりました。代表的な街道はどれですか？","choices":["東海道","山陽道だけ","日光街道だけ","すべて江戸時代には存在しない"],"answer":0,"a":"東海道などの五街道が整備されました。","term":"2学期"},{"id":"h19","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代の寺子屋で主に学ばれたものはどれですか？","choices":["読み書き・そろばん","外国語だけ","軍事学だけ","天文学だけ"],"answer":0,"a":"寺子屋では読み書きやそろばんなど、実生活に役立つ教育が行われました。","term":"2学期"},{"id":"h20","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に農業生産を高めるため広く利用された肥料はどれですか？","choices":["干鰯などの金肥","石炭","石油","化学肥料だけ"],"answer":0,"a":"干鰯や油かすなど、購入して使う金肥が利用されました。","term":"2学期"},{"id":"h21","category":"history","unit":"幕末","difficulty":"basic","q":"1853年に浦賀に来航したアメリカの使節は誰ですか？","choices":["ペリー","ハリス","マッカーサー","シーボルト"],"answer":0,"a":"ペリーが率いるアメリカ艦隊が浦賀に来航しました。","term":"2学期"},{"id":"h22","category":"history","unit":"幕末","difficulty":"basic","q":"1854年、日本とアメリカの間で結ばれた条約は何ですか？","choices":["日米和親条約","日米修好通商条約","ポーツマス条約","下関条約"],"answer":0,"a":"1854年に日米和親条約が結ばれました。","term":"2学期"},{"id":"h23","category":"history","unit":"幕末","difficulty":"standard","q":"1858年に結ばれた、領事裁判権を認め、関税自主権がないなどの内容を含む条約は何ですか？","choices":["日米修好通商条約","日米和親条約","サンフランシスコ平和条約","日英同盟"],"answer":0,"a":"日米修好通商条約は不平等条約とされる代表例です。","term":"2学期"},{"id":"h24","category":"history","unit":"幕末","difficulty":"standard","q":"江戸幕府が政権を朝廷に返した出来事を何といいますか？","choices":["大政奉還","版籍奉還","廃藩置県","王政復古"],"answer":0,"a":"1867年、徳川慶喜が大政奉還を行いました。","term":"2学期"},{"id":"h25","category":"history","unit":"幕末","difficulty":"standard","q":"薩摩藩と長州藩が同盟を結んだことを何といいますか？","choices":["薩長同盟","尊王攘夷","公武合体","五箇条の御誓文"],"answer":0,"a":"坂本龍馬らの仲介もあり、薩摩と長州が薩長同盟を結びました。","term":"2学期"},{"id":"h26","category":"history","unit":"幕末","difficulty":"basic","q":"江戸幕府が政権を朝廷に返したのは何年ですか？","choices":["1603年","1853年","1867年","1871年"],"answer":2,"a":"大政奉還は1867年です。","term":"2学期"},{"id":"h27","category":"history","unit":"明治維新","difficulty":"basic","q":"明治政府が1868年に新しい政治の方針として示したものは何ですか？","choices":["五箇条の御誓文","武家諸法度","御成敗式目","教育勅語"],"answer":0,"a":"五箇条の御誓文は新政府の基本方針を示しました。","term":"3学期"},{"id":"h28","category":"history","unit":"明治維新","difficulty":"basic","q":"1871年、藩を廃止して府県を置いた改革は何ですか？","choices":["廃藩置県","版籍奉還","地租改正","徴兵令"],"answer":0,"a":"1871年の廃藩置県によって中央集権化が進みました。","term":"3学期"},{"id":"h29","category":"history","unit":"明治維新","difficulty":"basic","q":"満20歳以上の男子に兵役を義務づける制度を定めたものは何ですか？","choices":["徴兵令","学制","地租改正","廃藩置県"],"answer":0,"a":"1873年に徴兵令が出されました。","term":"3学期"},{"id":"h30","category":"history","unit":"明治維新","difficulty":"standard","q":"土地の所有者に地券を発行し、地価を基準に税を現金で納めさせる改革は何ですか？","choices":["地租改正","徴兵令","廃藩置県","殖産興業"],"answer":0,"a":"地租改正では地価を基準に地租を現金で納める仕組みが整えられました。","term":"3学期"},{"id":"h31","category":"history","unit":"明治維新","difficulty":"basic","q":"明治政府が産業を育て、近代的な工業を発展させようとした政策を何といいますか？","choices":["殖産興業","鎖国","参勤交代","楽市楽座"],"answer":0,"a":"殖産興業は産業・工業の発展を目指す政策です。","term":"3学期"},{"id":"h32","category":"history","unit":"明治維新","difficulty":"standard","q":"1872年に出された近代的な学校制度は何ですか？","choices":["学制","教育基本法","武家諸法度","寺子屋令"],"answer":0,"a":"1872年に学制が公布されました。","term":"3学期"},{"id":"h33","category":"history","unit":"明治維新","difficulty":"standard","q":"文明開化の影響で広まったものとして適切なのはどれですか？","choices":["西洋の文化や生活様式","参勤交代","鎖国政策","武士の身分制度の強化"],"answer":0,"a":"文明開化では西洋の文化や生活様式が取り入れられました。","term":"3学期"},{"id":"h34","category":"history","unit":"明治維新","difficulty":"advanced","q":"明治政府が欧米諸国に追いつくため、産業や軍事の近代化を進めた背景として適切なのはどれですか？","choices":["欧米列強による圧力を受けたため","江戸幕府が復活したため","鎖国を強化するため","農業を廃止するため"],"answer":0,"a":"欧米列強の進出に対抗し、近代国家を形成することが大きな課題でした。","term":"3学期"},{"id":"h35","category":"history","unit":"明治維新","difficulty":"advanced","q":"「富国強兵」という政策の目的として最も適切なのはどれですか？","choices":["国を豊かにし軍事力を強化する","農業だけを発展させる","海外との交流を完全に止める","身分制度を復活させる"],"answer":0,"a":"富国強兵は経済力と軍事力を高め、近代国家をつくることを目指しました。","term":"3学期"},{"id":"c01","category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法の基本原理の一つはどれですか？","choices":["国民主権","封建制度","鎖国","身分制"],"answer":0,"a":"日本国憲法の基本原理には国民主権、基本的人権の尊重、平和主義があります。","term":"3学期"},{"id":"c02","category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法で、すべての国民が個人として尊重されることと関係が深いものはどれですか？","choices":["基本的人権の尊重","参勤交代","徴兵令","廃藩置県"],"answer":0,"a":"基本的人権の尊重は日本国憲法の基本原理の一つです。","term":"3学期"},{"id":"c03","category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法の三大原理に含まれるものはどれですか？","choices":["平和主義","富国強兵","殖産興業","鎖国"],"answer":0,"a":"平和主義は日本国憲法の基本原理の一つです。","term":"3学期"},{"id":"c04","category":"civics","unit":"基本的人権","difficulty":"basic","q":"人が生まれながらに持っている権利を何といいますか？","choices":["基本的人権","参政権だけ","納税義務","社会保障"],"answer":0,"a":"基本的人権は、個人が尊重されるための基本的な権利です。","term":"3学期"},{"id":"c05","category":"civics","unit":"基本的人権","difficulty":"standard","q":"日本国憲法で保障される「表現の自由」は何に分類されますか？","choices":["自由権","社会権","請求権","参政権"],"answer":0,"a":"表現の自由は自由権に含まれます。","term":"3学期"},{"id":"c06","category":"civics","unit":"基本的人権","difficulty":"standard","q":"教育を受ける権利や健康で文化的な最低限度の生活を営む権利と関係が深いのはどれですか？","choices":["社会権","自由権","参政権","請求権"],"answer":0,"a":"社会権には生存権や教育を受ける権利などがあります。","term":"3学期"},{"id":"c07","category":"civics","unit":"基本的人権","difficulty":"basic","q":"政治に参加する権利を何といいますか？","choices":["参政権","社会権","自由権","環境権"],"answer":0,"a":"参政権は選挙権など、政治に参加するための権利です。","term":"3学期"},{"id":"c08","category":"civics","unit":"日本国憲法","difficulty":"standard","q":"日本国憲法第9条と関係が深い原理はどれですか？","choices":["平和主義","地方自治","財産権","教育を受ける権利"],"answer":0,"a":"憲法9条は戦争の放棄などを定めており、平和主義と関係します。","term":"3学期"},{"id":"c09","category":"civics","unit":"国会","difficulty":"basic","q":"日本の国会は何と呼ばれる機関ですか？","choices":["国権の最高機関","司法の最高機関","地方自治の最高機関","行政の最高機関"],"answer":0,"a":"日本国憲法では国会を国権の最高機関であり、国の唯一の立法機関としています。","term":"3学期"},{"id":"c10","category":"civics","unit":"国会","difficulty":"basic","q":"日本の国会を構成する二つの議院はどれですか？","choices":["衆議院と参議院","上院と下院","地方院と国民院","内閣と裁判所"],"answer":0,"a":"日本の国会は衆議院と参議院の二院制です。","term":"3学期"},{"id":"c11","category":"civics","unit":"国会","difficulty":"standard","q":"衆議院と参議院のうち、解散があるのはどちらですか？","choices":["衆議院","参議院","両方","どちらにもない"],"answer":0,"a":"衆議院には解散があります。参議院には解散はありません。","term":"3学期"},{"id":"c12","category":"civics","unit":"内閣","difficulty":"basic","q":"行政の中心となる機関は何ですか？","choices":["内閣","国会","裁判所","地方議会"],"answer":0,"a":"内閣が行政権を担当します。","term":"3学期"},{"id":"c13","category":"civics","unit":"内閣","difficulty":"basic","q":"内閣の首長は誰ですか？","choices":["内閣総理大臣","衆議院議長","最高裁判所長官","財務大臣"],"answer":0,"a":"内閣の首長は内閣総理大臣です。","term":"3学期"},{"id":"c14","category":"civics","unit":"裁判所","difficulty":"basic","q":"司法権を担当する機関はどこですか？","choices":["裁判所","国会","内閣","地方議会"],"answer":0,"a":"裁判所が司法権を担当します。","term":"3学期"},{"id":"c15","category":"civics","unit":"裁判所","difficulty":"standard","q":"日本の司法制度の最高機関はどこですか？","choices":["最高裁判所","高等裁判所","地方裁判所","家庭裁判所"],"answer":0,"a":"最高裁判所は日本の裁判所の最上級に位置します。","term":"3学期"},{"id":"c16","category":"civics","unit":"三権分立","difficulty":"standard","q":"国会・内閣・裁判所が権力を分担する仕組みを何といいますか？","choices":["三権分立","地方自治","議院内閣制","直接民主制"],"answer":0,"a":"立法・行政・司法を分け、互いに抑制・均衡させる仕組みが三権分立です。","term":"3学期"},{"id":"c17","category":"civics","unit":"地方自治","difficulty":"basic","q":"地方公共団体が地域のことを自ら決めることを何といいますか？","choices":["地方自治","国民主権","三権分立","直接請求"],"answer":0,"a":"地方自治は地域住民の意思を反映して地域を運営する考え方です。","term":"3学期"},{"id":"c18","category":"civics","unit":"地方自治","difficulty":"basic","q":"都道府県や市区町村の長を何と呼びますか？","choices":["首長","議長","裁判官","国務大臣"],"answer":0,"a":"都道府県知事や市区町村長を首長といいます。","term":"3学期"},{"id":"c19","category":"civics","unit":"地方自治","difficulty":"standard","q":"地方公共団体の議会の議員や首長を住民が直接選ぶ制度と関係が深いものはどれですか？","choices":["直接選挙","間接選挙","任命制","世襲制"],"answer":0,"a":"地方自治では住民が首長や議員を直接選挙します。","term":"3学期"},{"id":"c20","category":"civics","unit":"選挙","difficulty":"basic","q":"日本で国民が代表者を選挙によって選び、政治を行う仕組みを何といいますか？","choices":["間接民主制","専制政治","封建制度","君主制"],"answer":0,"a":"日本は代表者を選ぶ間接民主制を基本としています。","term":"3学期"},{"id":"c21","category":"civics","unit":"選挙","difficulty":"standard","q":"選挙で一人の有権者が一票を持つ原則を何といいますか？","choices":["普通選挙","平等選挙","秘密選挙","直接選挙"],"answer":1,"a":"一人一票の原則は平等選挙です。","term":"3学期"},{"id":"c22","category":"civics","unit":"選挙","difficulty":"standard","q":"誰に投票したかを他人に知られないようにする原則は何ですか？","choices":["秘密選挙","平等選挙","直接選挙","普通選挙"],"answer":0,"a":"秘密選挙は投票内容を他人に知られないようにする原則です。","term":"3学期"},{"id":"c23","category":"civics","unit":"消費生活","difficulty":"basic","q":"商品やサービスを購入して生活する人を何といいますか？","choices":["消費者","生産者","納税者だけ","裁判員"],"answer":0,"a":"商品やサービスを購入して利用する人を消費者といいます。","term":"3学期"},{"id":"c24","category":"civics","unit":"消費生活","difficulty":"standard","q":"契約は原則として、どのような意思が合致することで成立しますか？","choices":["申し込みと承諾","広告と口コミ","値札とレシート","電話とメール"],"answer":0,"a":"契約は当事者の申し込みと承諾の意思が合致することで成立します。","term":"3学期"},{"id":"c25","category":"civics","unit":"現代社会","difficulty":"advanced","q":"情報社会で情報を受け取る際に特に大切な姿勢はどれですか？","choices":["複数の情報源を確認する","最初に見た情報を必ず信じる","見出しだけで判断する","発信者を確認しない"],"answer":0,"a":"情報の正確性や根拠を確認し、複数の情報源を比較することが重要です。","term":"3学期"},{"id":"g41","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の東西・南北を通る位置を表すときに使う2種類の線の組み合わせはどれですか？","choices":["経線と緯線","等高線と境界線","海岸線と河川","断層線と等深線"],"answer":0,"a":"経線は東西の位置（経度）、緯線は南北の位置（緯度）を表します。","term":"1学期"},{"id":"g42","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の都道府県で「府」と呼ばれるのはどこですか？","choices":["大阪府と京都府","東京都と大阪府","北海道と京都府","沖縄県と大阪府"],"answer":0,"a":"「府」は大阪府と京都府の2つです。","term":"1学期"},{"id":"g43","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"日本の地方区分で、福岡県・熊本県などが含まれるのはどこですか？","choices":["九州地方","中国地方","四国地方","近畿地方"],"answer":0,"a":"福岡県や熊本県などは九州地方に属します。","term":"1学期"},{"id":"g44","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"愛知県を含む地方はどこですか？","choices":["中部地方","関東地方","近畿地方","中国地方"],"answer":0,"a":"愛知県は中部地方に含まれます。","term":"1学期"},{"id":"g45","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"鳥取県・島根県などが含まれる地方はどこですか？","choices":["中国地方","四国地方","近畿地方","九州地方"],"answer":0,"a":"鳥取県・島根県・岡山県・広島県・山口県は中国地方です。","term":"1学期"},{"id":"g46","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"香川県・愛媛県などが含まれる地方はどこですか？","choices":["四国地方","九州地方","中国地方","近畿地方"],"answer":0,"a":"香川県・愛媛県・徳島県・高知県は四国地方です。","term":"1学期"},{"id":"g47","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"滋賀県・奈良県などを含む地方はどこですか？","choices":["近畿地方","中部地方","関東地方","東北地方"],"answer":0,"a":"滋賀県・奈良県・大阪府・京都府・兵庫県・和歌山県・三重県は近畿地方に区分されます。","term":"1学期"},{"id":"g48","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"宮城県・岩手県などが含まれる地方はどこですか？","choices":["東北地方","北海道地方","関東地方","中部地方"],"answer":0,"a":"宮城県・岩手県などは東北地方です。","term":"1学期"},{"id":"g49","category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"茨城県・栃木県・群馬県などが含まれる地方はどこですか？","choices":["関東地方","東北地方","中部地方","近畿地方"],"answer":0,"a":"茨城・栃木・群馬・埼玉・千葉・東京・神奈川は関東地方です。","term":"1学期"},{"id":"g50","category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"新潟県・長野県などが含まれる地方は一般にどこですか？","choices":["中部地方","関東地方","東北地方","近畿地方"],"answer":0,"a":"新潟県や長野県は中部地方に含まれます。","term":"1学期"},{"id":"g51","category":"geography","unit":"人口","difficulty":"basic","q":"人口の自然増減を考えるとき、出生数から何を引きますか？","choices":["死亡数","転入数","転出数","世帯数"],"answer":0,"a":"自然増減は出生数と死亡数の差です。","term":"1学期"},{"id":"g52","category":"geography","unit":"人口","difficulty":"standard","q":"他の地域から人が入ってきて人口が増えることを何といいますか？","choices":["転入","転出","自然減","過疎"],"answer":0,"a":"他地域から移ってくることを転入といいます。","term":"1学期"},{"id":"g53","category":"geography","unit":"人口","difficulty":"standard","q":"ある地域から他の地域へ人が移って出ていくことを何といいますか？","choices":["転出","転入","出生","高齢化"],"answer":0,"a":"地域から移って出ていくことを転出といいます。","term":"1学期"},{"id":"g54","category":"geography","unit":"人口","difficulty":"standard","q":"少子化とは何が減少する傾向を指しますか？","choices":["子どもの数や出生数","高齢者の数","都市の数","外国人旅行者数"],"answer":0,"a":"少子化は出生数の減少などにより子どもの割合が低下する傾向です。","term":"1学期"},{"id":"g55","category":"geography","unit":"人口","difficulty":"advanced","q":"人口の都市集中が進むと、中心都市と周辺地域の間で生じやすい課題はどれですか？","choices":["地域間の人口・サービス格差","地震の発生がゼロになる","降水量が全国で同じになる","山地が平地になる"],"answer":0,"a":"人口集中は地域間の人口や公共サービスの維持などに差を生むことがあります。","term":"1学期"},{"id":"g56","category":"geography","unit":"産業","difficulty":"basic","q":"農業・林業・漁業が第一次産業に分類される理由として適切なのはどれですか？","choices":["自然から資源を直接得る産業だから","工場で加工する産業だから","販売だけを行う産業だから","情報を伝える産業だから"],"answer":0,"a":"第一次産業は自然界から資源を直接得る産業です。","term":"1学期"},{"id":"g57","category":"geography","unit":"産業","difficulty":"standard","q":"工場で原料を加工して製品をつくる産業は何次産業ですか？","choices":["第一次","第二次","第三次","第四次"],"answer":1,"a":"製造業などは第二次産業です。","term":"1学期"},{"id":"g58","category":"geography","unit":"産業","difficulty":"basic","q":"銀行・ホテル・小売店などの多くは何次産業に分類されますか？","choices":["第一次","第二次","第三次","第五次"],"answer":2,"a":"銀行・ホテル・小売などのサービス関連産業は第三次産業です。","term":"1学期"},{"id":"g59","category":"geography","unit":"産業","difficulty":"standard","q":"都市の消費者に近いことを生かして行う農業の例として適切なのはどれですか？","choices":["近郊農業","焼畑農業","高地農業だけ","遊牧"],"answer":0,"a":"大都市周辺で野菜などを生産する近郊農業は消費地に近いことを生かします。","term":"1学期"},{"id":"g60","category":"geography","unit":"産業","difficulty":"standard","q":"ビニールハウスなどを利用して出荷時期を早める農業はどれですか？","choices":["促成栽培","抑制栽培","輪作","休耕"],"answer":0,"a":"促成栽培は生育を早めて出荷時期を早める栽培方法です。","term":"1学期"},{"id":"g61","category":"geography","unit":"産業","difficulty":"standard","q":"野菜などの出荷時期を遅らせて価格の高い時期に出荷しやすくする方法はどれですか？","choices":["抑制栽培","促成栽培","二期作","焼畑"],"answer":0,"a":"抑制栽培は出荷時期を遅らせる方法です。","term":"1学期"},{"id":"g62","category":"geography","unit":"産業","difficulty":"standard","q":"北海道の十勝地方で特に盛んな農業はどれですか？","choices":["畑作","茶栽培","みかん栽培","さとうきび栽培"],"answer":0,"a":"十勝地方では大規模な畑作が盛んです。","term":"1学期"},{"id":"g63","category":"geography","unit":"産業","difficulty":"standard","q":"北海道で広い土地を利用して乳牛を育てる農業が盛んな地域として知られるのはどこですか？","choices":["根釧台地","讃岐平野","濃尾平野","庄内平野"],"answer":0,"a":"根釧台地などでは酪農が盛んです。","term":"1学期"},{"id":"g64","category":"geography","unit":"産業","difficulty":"standard","q":"静岡県などで盛んな農産物として代表的なのはどれですか？","choices":["茶","小麦","てんさい","パイナップルだけ"],"answer":0,"a":"静岡県は茶の生産で知られています。","term":"1学期"},{"id":"g65","category":"geography","unit":"産業","difficulty":"standard","q":"沖縄県で栽培が盛んな作物として代表的なのはどれですか？","choices":["さとうきび","てんさい","りんご","そば"],"answer":0,"a":"沖縄県では温暖な気候を生かしてさとうきび栽培が盛んです。","term":"1学期"},{"id":"g66","category":"geography","unit":"産業","difficulty":"standard","q":"工業が港に近い場所に立地する理由として最も適切なのはどれですか？","choices":["原料・製品の大量輸送に便利だから","雪が必ず少ないから","人口が必ず少ないから","山地が多いから"],"answer":0,"a":"港は原料や製品を船で大量に運ぶのに適しています。","term":"1学期"},{"id":"g67","category":"geography","unit":"産業","difficulty":"standard","q":"自動車工業が盛んな地域として知られる愛知県で中心となる都市はどこですか？","choices":["豊田市","函館市","高知市","鳥取市"],"answer":0,"a":"愛知県の豊田市周辺は自動車工業が盛んな地域です。","term":"1学期"},{"id":"g68","category":"geography","unit":"産業","difficulty":"advanced","q":"工業の立地で「市場に近い」ことが特に重要になりやすい産業はどれですか？","choices":["消費者向け食品などの加工業","鉄鉱石の採掘だけ","原油の採掘だけ","森林の伐採だけ"],"answer":0,"a":"消費地に近いことが鮮度や輸送費の面で重要になる加工業があります。","term":"1学期"},{"id":"g69","category":"geography","unit":"産業","difficulty":"advanced","q":"情報通信技術の発達によって、場所の制約を受けにくくなった仕事の例として適切なのはどれですか？","choices":["オンラインでの情報処理業務","漁業だけ","林業だけ","鉱山採掘だけ"],"answer":0,"a":"情報通信技術は情報を扱う仕事の立地条件を変えることがあります。","term":"1学期"},{"id":"g70","category":"geography","unit":"気候","difficulty":"basic","q":"日本で季節によって風向きが変わる大きな原因の一つは何ですか？","choices":["季節風","赤道","潮汐","断層"],"answer":0,"a":"季節によって大陸と海洋の温まり方が変わり、季節風が吹きます。","term":"2学期"},{"id":"g71","category":"geography","unit":"気候","difficulty":"standard","q":"冬の季節風が日本海を渡るとき、水蒸気を多く含む主な理由はどれですか？","choices":["海面から水蒸気を取り込むため","山から水が湧くため","日射が強すぎるため","台風になるため"],"answer":0,"a":"大陸からの冷たい風が日本海で水蒸気を取り込み、雪雲を発達させます。","term":"2学期"},{"id":"g72","category":"geography","unit":"気候","difficulty":"standard","q":"日本海側で冬に積雪が多くなりやすい地域の地形的特徴はどれですか？","choices":["山地が背後にある地域が多い","砂漠が広がる","平野しかない","熱帯雨林がある"],"answer":0,"a":"日本海側では雪雲が山地にぶつかり、降雪が多くなる地域があります。","term":"2学期"},{"id":"g73","category":"geography","unit":"気候","difficulty":"standard","q":"太平洋側で冬に晴天が多く乾燥しやすい原因として適切なのはどれですか？","choices":["山地を越えて乾いた空気が流れ込むため","黒潮がなくなるため","赤道が移動するため","梅雨前線が一年中停滞するため"],"answer":0,"a":"日本海側で雪を降らせた後の空気が乾燥して太平洋側へ流れ込むことがあります。","term":"2学期"},{"id":"g74","category":"geography","unit":"気候","difficulty":"basic","q":"梅雨の時期に日本付近に停滞しやすい前線は何ですか？","choices":["梅雨前線","寒冷前線だけ","温暖前線だけ","赤道前線"],"answer":0,"a":"梅雨の時期には梅雨前線が日本付近に停滞します。","term":"2学期"},{"id":"g75","category":"geography","unit":"気候","difficulty":"standard","q":"台風が日本に接近しやすい時期の特徴として適切なのはどれですか？","choices":["夏から秋にかけて多い","冬だけに集中する","春だけに集中する","一年中全く来ない"],"answer":0,"a":"日本では夏から秋にかけて台風の影響を受けやすくなります。","term":"2学期"},{"id":"g76","category":"geography","unit":"気候","difficulty":"advanced","q":"同じ緯度でも海沿いと内陸で気温差が生じる理由として適切なのはどれですか？","choices":["海は温まりにくく冷えにくい性質があるため","内陸には必ず雪が降るため","海では風が吹かないため","緯度が変わるため"],"answer":0,"a":"水は陸地よりも温まりにくく冷えにくいため、海は気温の変化を和らげます。","term":"2学期"},{"id":"g77","category":"geography","unit":"自然災害","difficulty":"basic","q":"急な大雨によって山の斜面から土砂や岩石が流れ下る災害を何といいますか？","choices":["土石流","高潮","津波","干ばつ"],"answer":0,"a":"土石流は大雨などで土砂や岩石が一気に流れ下る災害です。","term":"2学期"},{"id":"g78","category":"geography","unit":"自然災害","difficulty":"basic","q":"急な大雨などで斜面が崩れ落ちる災害は何ですか？","choices":["がけ崩れ","高潮","液状化","津波"],"answer":0,"a":"急傾斜地などが崩れる災害をがけ崩れといいます。","term":"2学期"},{"id":"g79","category":"geography","unit":"自然災害","difficulty":"standard","q":"海面が台風などによって異常に上昇する現象を何といいますか？","choices":["高潮","津波","洪水","土石流"],"answer":0,"a":"台風や低気圧による海面上昇を高潮といいます。","term":"2学期"},{"id":"g80","category":"geography","unit":"自然災害","difficulty":"standard","q":"災害が起きる前から地域で避難方法を確認することを何という活動に含められますか？","choices":["防災","復旧","観光","工業化"],"answer":0,"a":"災害に備えて避難方法などを確認することは防災の重要な活動です。","term":"2学期"},{"id":"g81","category":"geography","unit":"自然災害","difficulty":"advanced","q":"災害への備えで「自助」にあたるものはどれですか？","choices":["自分や家族の安全を守る備え","行政が行う救助活動","地域全体の清掃だけ","企業の広告活動"],"answer":0,"a":"自助は自分や家族で身を守るための備えや行動です。","term":"2学期"},{"id":"g82","category":"geography","unit":"自然災害","difficulty":"advanced","q":"地域住民が協力して避難や救助を行うことを表す考え方はどれですか？","choices":["共助","公助","自然減","産業立地"],"answer":0,"a":"共助は地域や近隣の人々が互いに助け合うことです。","term":"2学期"},{"id":"g83","category":"geography","unit":"自然災害","difficulty":"basic","q":"地震の揺れの大きさを表す「震度」は、どの地域の揺れを表しますか？","choices":["ある地点での揺れの強さ","地震そのものの規模だけ","津波の高さ","雨量"],"answer":0,"a":"震度は各地点で実際に観測された揺れの強さを表します。","term":"2学期"},{"id":"g84","category":"geography","unit":"自然災害","difficulty":"standard","q":"地震そのものの規模を表す指標はどれですか？","choices":["マグニチュード","震度","降水量","風速"],"answer":0,"a":"マグニチュードは地震そのものの規模を表す指標です。","term":"2学期"},{"id":"g85","category":"geography","unit":"地域調査","difficulty":"basic","q":"地形図の「凡例」は何のために使いますか？","choices":["地図記号などの意味を確認するため","人口を数えるため","地震を予知するため","気温を測るため"],"answer":0,"a":"凡例では地図記号などの意味を確認できます。","term":"1学期"},{"id":"g86","category":"geography","unit":"地域調査","difficulty":"standard","q":"地形図で等高線の間隔が狭い場所は、一般にどのような地形ですか？","choices":["傾斜が急","傾斜が緩やか","平らな海面","必ず川がある"],"answer":0,"a":"等高線の間隔が狭い場所は標高が短い距離で変化するため、傾斜が急です。","term":"1学期"},{"id":"g87","category":"geography","unit":"地域調査","difficulty":"standard","q":"地図上で北の方角を示すために使われる記号は一般に何ですか？","choices":["方位記号","縮尺記号だけ","等高線","凡例だけ"],"answer":0,"a":"方位記号によって地図上の方位を確認できます。","term":"1学期"},{"id":"g88","category":"geography","unit":"地域調査","difficulty":"advanced","q":"縮尺1:25,000の地図で1cmが表す実際の距離はどれですか？","choices":["250m","25m","2.5km","25km"],"answer":0,"a":"1:25,000では1cm×25,000＝25,000cm＝250mです。","term":"1学期"},{"id":"g89","category":"geography","unit":"地域調査","difficulty":"advanced","q":"縮尺1:50,000の地図で2cmは実際には何kmですか？","choices":["1km","2km","5km","10km"],"answer":0,"a":"2cm×50,000＝100,000cm＝1kmです。","term":"1学期"},{"id":"g90","category":"geography","unit":"地域調査","difficulty":"standard","q":"地域調査で聞き取り調査を行う主な目的はどれですか？","choices":["地域の人の経験や意見などを知る","地図の縮尺を変更する","台風を止める","地震をなくす"],"answer":0,"a":"聞き取りでは統計だけでは分からない地域の経験や意見を得られます。","term":"1学期"},{"id":"g91","category":"geography","unit":"地域調査","difficulty":"basic","q":"人口密度は何を表す値ですか？","choices":["一定の面積あたりの人口","一年間の出生数","市町村の数","土地の高さ"],"answer":0,"a":"人口密度は単位面積あたりの人口です。","term":"1学期"},{"id":"g92","category":"geography","unit":"地域調査","difficulty":"standard","q":"人口密度を求める基本的な計算はどれですか？","choices":["人口÷面積","面積÷人口","人口×面積","人口＋面積"],"answer":0,"a":"人口密度は人口を面積で割って求めます。","term":"1学期"},{"id":"g93","category":"geography","unit":"日本の諸地域","difficulty":"standard","q":"東北地方で米作りが盛んな平野として知られるのはどこですか？","choices":["庄内平野","濃尾平野","宮崎平野","高知平野"],"answer":0,"a":"山形県の庄内平野など東北地方では稲作が盛んです。","term":"1学期"},{"id":"g94","category":"geography","unit":"日本の諸地域","difficulty":"standard","q":"関東地方に日本最大の平野として広がるのはどこですか？","choices":["関東平野","石狩平野","筑紫平野","越後平野"],"answer":0,"a":"関東平野は日本最大の平野です。","term":"1学期"},{"id":"g95","category":"geography","unit":"日本の諸地域","difficulty":"standard","q":"中部地方の内陸部で果樹栽培が盛んな地域の例はどれですか？","choices":["甲府盆地","石狩平野","十勝平野","筑紫平野"],"answer":0,"a":"山梨県の甲府盆地などではぶどうやももなどの果樹栽培が盛んです。","term":"1学期"},{"id":"g96","category":"geography","unit":"日本の諸地域","difficulty":"standard","q":"近畿地方で大都市圏を形成する組み合わせとして適切なのはどれですか？","choices":["大阪・京都・神戸","札幌・仙台・福岡","名古屋・金沢・長野","高知・松山・徳島"],"answer":0,"a":"大阪・京都・神戸を中心とする地域は京阪神大都市圏と呼ばれます。","term":"1学期"},{"id":"g97","category":"geography","unit":"日本の諸地域","difficulty":"standard","q":"瀬戸内海沿岸で工業が発達した理由の一つはどれですか？","choices":["海上交通を利用しやすいから","一年中豪雪だから","高地が広がるから","人口が極端に少ないから"],"answer":0,"a":"瀬戸内海は波が比較的穏やかで海上交通を利用しやすいことが工業立地に関係します。","term":"1学期"},{"id":"g98","category":"geography","unit":"日本の諸地域","difficulty":"standard","q":"九州北部で工業が発展する一因となった地域として知られるのはどこですか？","choices":["北九州工業地域","京葉工業地域","京浜工業地帯","東海工業地域"],"answer":0,"a":"北九州工業地域は八幡製鉄所などを中心に発展しました。","term":"1学期"},{"id":"g99","category":"geography","unit":"日本の諸地域","difficulty":"advanced","q":"沖縄県の産業や生活と特に関係が深い自然条件はどれですか？","choices":["温暖な亜熱帯の気候","豪雪地帯であること","大規模な内陸盆地","寒帯気候"],"answer":0,"a":"沖縄県は温暖な気候を生かした農業や観光などが発達しています。","term":"1学期"},{"id":"g100","category":"geography","unit":"日本の諸地域","difficulty":"advanced","q":"北海道の広い土地を生かした農業の特徴として適切なのはどれですか？","choices":["大規模な機械化農業","棚田だけの稲作","都市近郊農業だけ","茶園中心の農業"],"answer":0,"a":"北海道では広い土地を生かした大規模で機械化された農業が見られます。","term":"1学期"},{"id":"h36","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸幕府が朝廷と大名の関係を保つために利用した制度の一つはどれですか？","choices":["武家諸法度","学制","徴兵令","五箇条の御誓文"],"answer":0,"a":"武家諸法度は大名統制の基本となる法令でした。","term":"2学期"},{"id":"h37","category":"history","unit":"江戸時代","difficulty":"standard","q":"親藩・譜代・外様という分類は何を区分したものですか？","choices":["大名","農民","町人","寺社"],"answer":0,"a":"親藩・譜代・外様は江戸幕府が大名を分類したものです。","term":"2学期"},{"id":"h38","category":"history","unit":"江戸時代","difficulty":"standard","q":"関ヶ原の戦いの後、徳川家康が征夷大将軍に任命されたのは何年ですか？","choices":["1600年","1603年","1615年","1639年"],"answer":1,"a":"徳川家康は1603年に征夷大将軍に任命されました。","term":"2学期"},{"id":"h39","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸幕府が諸大名に江戸への参勤を命じた主なねらいはどれですか？","choices":["大名を統制する","農民を増やす","鎖国をやめる","外国語を広める"],"answer":0,"a":"参勤交代は大名の統制を目的とした制度の一つです。","term":"2学期"},{"id":"h40","category":"history","unit":"江戸時代","difficulty":"standard","q":"幕府が直接支配した土地を何といいますか？","choices":["天領","藩領","私領","公領"],"answer":0,"a":"幕府の直轄地は天領などと呼ばれます。","term":"2学期"},{"id":"h41","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代の身分社会で、農村に住み農業を営んだ人々の中心は誰ですか？","choices":["百姓","武士","公家","大名"],"answer":0,"a":"農村で農業を営む人々を百姓と呼びました。","term":"2学期"},{"id":"h42","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代の都市で商業を担った人々を何と呼びましたか？","choices":["町人","大名","公家","将軍"],"answer":0,"a":"都市で商工業を担った人々を町人と呼びました。","term":"2学期"},{"id":"h43","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代の身分制度で、武士が支配する側に位置したことを示す語として適切なのはどれですか？","choices":["支配身分","被支配身分","農業身分","工業身分"],"answer":0,"a":"武士は政治権力を担い、支配身分として位置づけられました。","term":"2学期"},{"id":"h44","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代の村をまとめた代表者は何と呼ばれましたか？","choices":["庄屋","大老","奉行","町奉行"],"answer":0,"a":"庄屋（名主など）が村の行政を担いました。","term":"2学期"},{"id":"h45","category":"history","unit":"江戸時代","difficulty":"standard","q":"五人組の役割として適切なのはどれですか？","choices":["連帯責任で年貢や犯罪防止などを支える","外国との貿易を行う","藩主を選ぶ","裁判所を運営する"],"answer":0,"a":"五人組は農民などを組織し、連帯責任で統制する仕組みでした。","term":"2学期"},{"id":"h46","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代に新田開発が進められた主な目的はどれですか？","choices":["耕地と収穫量を増やす","港を閉鎖する","城を増やす","外国人を増やす"],"answer":0,"a":"新田開発で耕地を増やし、農業生産を高めました。","term":"2学期"},{"id":"h47","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に商品作物として栽培が広がったものはどれですか？","choices":["綿花","稲だけ","サンゴだけ","石炭だけ"],"answer":0,"a":"綿花などの商品作物の栽培が広がりました。","term":"2学期"},{"id":"h48","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に農村で手工業が発展したことを示す語はどれですか？","choices":["農村工業","重工業化","工業地帯","第三次産業化"],"answer":0,"a":"農村で織物などを行う農村工業が発達しました。","term":"2学期"},{"id":"h49","category":"history","unit":"江戸時代","difficulty":"basic","q":"大阪が「天下の台所」と呼ばれた理由として適切なのはどれですか？","choices":["米などの物資が集まり商業が盛んだったから","江戸幕府の城があったから","日本で最も高い山があったから","外国の首都だったから"],"answer":0,"a":"大阪は米をはじめ全国の物資が集まる商業都市として栄えました。","term":"2学期"},{"id":"h50","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に商人が行った大規模な商取引の仕組みとして発達したものはどれですか？","choices":["株仲間","五人組","参勤交代","廃藩置県"],"answer":0,"a":"株仲間は商人や職人がつくった同業者組織です。","term":"2学期"},{"id":"h51","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に商人が現金や手形などを扱った金融の中心地として発達したのはどこですか？","choices":["大阪","鎌倉","平泉","太宰府"],"answer":0,"a":"大阪は商業・金融の中心地としても栄えました。","term":"2学期"},{"id":"h52","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代の五街道の一つで、江戸と京都を結んだ街道はどれですか？","choices":["東海道","奥州街道だけ","中山道だけではない","山陰道"],"answer":0,"a":"東海道は江戸と京都を結ぶ主要街道でした。","term":"2学期"},{"id":"h53","category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代の宿場町は主に何のために発達しましたか？","choices":["街道を行き来する人や荷物を支えるため","農地をなくすため","城を破壊するため","外国貿易を独占するため"],"answer":0,"a":"宿場町は旅人の宿泊や輸送などの拠点として発達しました。","term":"2学期"},{"id":"h54","category":"history","unit":"江戸時代","difficulty":"basic","q":"元禄文化が特に栄えた地域はどこですか？","choices":["上方（大阪・京都周辺）","北海道のみ","九州南部のみ","江戸だけ"],"answer":0,"a":"元禄文化は上方を中心に栄えました。","term":"2学期"},{"id":"h55","category":"history","unit":"江戸時代","difficulty":"standard","q":"井原西鶴が書いた作品として知られるのはどれですか？","choices":["好色一代男","南総里見八犬伝","東海道中膝栗毛","富嶽百景"],"answer":0,"a":"井原西鶴は『好色一代男』などで知られます。","term":"2学期"},{"id":"h56","category":"history","unit":"江戸時代","difficulty":"standard","q":"近松門左衛門が活躍した分野はどれですか？","choices":["人形浄瑠璃・歌舞伎の脚本","医学だけ","地図作成だけ","軍事学だけ"],"answer":0,"a":"近松門左衛門は人形浄瑠璃などの脚本で活躍しました。","term":"2学期"},{"id":"h57","category":"history","unit":"江戸時代","difficulty":"standard","q":"松尾芭蕉の作品として知られるのはどれですか？","choices":["奥の細道","解体新書","蘭学事始","方丈記"],"answer":0,"a":"松尾芭蕉は『奥の細道』などで知られます。","term":"2学期"},{"id":"h58","category":"history","unit":"江戸時代","difficulty":"standard","q":"葛飾北斎の代表作として知られるのはどれですか？","choices":["富嶽三十六景","見返り美人図","南総里見八犬伝","好色一代男"],"answer":0,"a":"葛飾北斎は『富嶽三十六景』などの浮世絵で知られます。","term":"2学期"},{"id":"h59","category":"history","unit":"江戸時代","difficulty":"standard","q":"歌川広重が描いた作品として代表的なのはどれですか？","choices":["東海道五十三次","解体新書","奥の細道","蘭学事始"],"answer":0,"a":"歌川広重は『東海道五十三次』などの風景版画で知られます。","term":"2学期"},{"id":"h60","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代に発達した大衆的な演劇はどれですか？","choices":["歌舞伎","能だけ","雅楽だけ","オペラ"],"answer":0,"a":"歌舞伎は江戸時代に大衆文化として発展しました。","term":"2学期"},{"id":"h61","category":"history","unit":"江戸時代","difficulty":"standard","q":"化政文化が特に栄えた都市はどこですか？","choices":["江戸","奈良","鎌倉","太宰府"],"answer":0,"a":"化政文化は19世紀前半の江戸を中心に栄えました。","term":"2学期"},{"id":"h62","category":"history","unit":"江戸時代","difficulty":"standard","q":"十返舎一九の作品として知られるのはどれですか？","choices":["東海道中膝栗毛","富嶽三十六景","解体新書","好色一代男"],"answer":0,"a":"十返舎一九は『東海道中膝栗毛』の作者です。","term":"2学期"},{"id":"h63","category":"history","unit":"江戸時代","difficulty":"standard","q":"滝沢馬琴の作品として知られるのはどれですか？","choices":["南総里見八犬伝","奥の細道","東海道五十三次","浮世風呂"],"answer":0,"a":"滝沢馬琴は『南総里見八犬伝』などで知られます。","term":"2学期"},{"id":"h64","category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代に庶民の教育を担った施設として代表的なのはどれですか？","choices":["寺子屋","大学校","藩閥学校","帝国大学"],"answer":0,"a":"寺子屋では読み書き・そろばんなどを学びました。","term":"2学期"},{"id":"h65","category":"history","unit":"江戸時代","difficulty":"standard","q":"幕府が庶民に倹約などを求めた政策の一つはどれですか？","choices":["倹約令","徴兵令","学制","五箇条の御誓文"],"answer":0,"a":"江戸時代の改革では倹約令などが出されました。","term":"2学期"},{"id":"h66","category":"history","unit":"江戸時代","difficulty":"standard","q":"享保の改革を行った将軍は誰ですか？","choices":["徳川吉宗","徳川家康","徳川綱吉","徳川慶喜"],"answer":0,"a":"徳川吉宗が享保の改革を行いました。","term":"2学期"},{"id":"h67","category":"history","unit":"江戸時代","difficulty":"standard","q":"寛政の改革を進めた老中は誰ですか？","choices":["松平定信","水野忠邦","田沼意次","井伊直弼"],"answer":0,"a":"松平定信が寛政の改革を進めました。","term":"2学期"},{"id":"h68","category":"history","unit":"江戸時代","difficulty":"standard","q":"天保の改革を進めた老中は誰ですか？","choices":["水野忠邦","松平定信","田沼意次","大久保利通"],"answer":0,"a":"水野忠邦が天保の改革を進めました。","term":"2学期"},{"id":"h69","category":"history","unit":"江戸時代","difficulty":"advanced","q":"田沼意次の政治の特徴として説明されることが多いのはどれですか？","choices":["商業や貨幣経済を重視した","鎖国を完全に廃止した","廃藩置県を行った","徴兵令を出した"],"answer":0,"a":"田沼意次は商業の発展や株仲間などを利用して幕府財政の立て直しを図りました。","term":"2学期"},{"id":"h70","category":"history","unit":"江戸時代","difficulty":"advanced","q":"寛政の改革で重視された考えとして適切なのはどれですか？","choices":["倹約と農村の立て直し","海外貿易の自由化","工業化の促進だけ","廃藩置県"],"answer":0,"a":"寛政の改革では倹約や農村復興などが進められました。","term":"2学期"},{"id":"h71","category":"history","unit":"江戸時代","difficulty":"advanced","q":"天保の改革で株仲間を解散させた主なねらいはどれですか？","choices":["物価引き下げをねらったため","外国軍を強化するため","学校を増やすため","参勤交代を廃止するため"],"answer":0,"a":"株仲間を解散させて商業を統制し、物価を下げようとしました。","term":"2学期"},{"id":"h72","category":"history","unit":"幕末","difficulty":"basic","q":"ロシアから長崎に来航し通商を求めた人物は誰ですか？","choices":["ラクスマン","ペリー","ハリス","シーボルト"],"answer":0,"a":"ラクスマンは1792年に根室へ来航し通商を求めました。","term":"2学期"},{"id":"h73","category":"history","unit":"幕末","difficulty":"standard","q":"1804年、長崎に来航し通商を求めたロシア使節は誰ですか？","choices":["レザノフ","ペリー","ハリス","プチャーチン"],"answer":0,"a":"レザノフは1804年に長崎に来航しました。","term":"2学期"},{"id":"h74","category":"history","unit":"幕末","difficulty":"standard","q":"外国船打払令を出した幕府の時期として最も近いのはどれですか？","choices":["19世紀前半","17世紀初め","15世紀末","20世紀初め"],"answer":0,"a":"外国船打払令は19世紀前半の1825年に出されました。","term":"2学期"},{"id":"h75","category":"history","unit":"幕末","difficulty":"standard","q":"外国船打払令をやめ、1842年に出された政策は何ですか？","choices":["薪水給与令","五箇条の御誓文","廃藩置県","徴兵令"],"answer":0,"a":"1842年、外国船打払令をやめ薪水給与令が出されました。","term":"2学期"},{"id":"h76","category":"history","unit":"幕末","difficulty":"basic","q":"1853年のペリー来航で幕府に強い衝撃を与えたものは何ですか？","choices":["アメリカ艦隊の来航","イギリス軍の上陸","フランス革命","日露戦争"],"answer":0,"a":"ペリー率いるアメリカ艦隊の来航は幕府に大きな衝撃を与えました。","term":"2学期"},{"id":"h77","category":"history","unit":"幕末","difficulty":"standard","q":"日米和親条約で開港した2港はどれですか？","choices":["下田と函館","長崎と横浜","神戸と新潟","大阪と江戸"],"answer":0,"a":"日米和親条約で下田と函館が開港されました。","term":"2学期"},{"id":"h78","category":"history","unit":"幕末","difficulty":"standard","q":"日米修好通商条約を結んだとき、アメリカ側の人物は誰ですか？","choices":["ハリス","ペリー","ラクスマン","レザノフ"],"answer":0,"a":"タウンゼント・ハリスが日本と通商条約を結びました。","term":"2学期"},{"id":"h79","category":"history","unit":"幕末","difficulty":"standard","q":"安政の五か国条約に含まれた国はどれですか？","choices":["アメリカ・オランダ・ロシア・イギリス・フランス","中国だけ","朝鮮だけ","ドイツだけ"],"answer":0,"a":"アメリカなど5か国との修好通商条約が結ばれました。","term":"2学期"},{"id":"h80","category":"history","unit":"幕末","difficulty":"advanced","q":"不平等条約の内容として問題視されたものはどれですか？","choices":["領事裁判権を認め、関税自主権がなかったこと","選挙権を与えたこと","地方自治を認めたこと","学校を増やしたこと"],"answer":0,"a":"領事裁判権の承認や関税自主権がなかったことが不平等な点でした。","term":"2学期"},{"id":"h81","category":"history","unit":"幕末","difficulty":"basic","q":"幕末に「外国勢力を追い払おう」という主張を何といいますか？","choices":["攘夷","尊王","公議","文明開化"],"answer":0,"a":"攘夷は外国勢力を追い払おうとする考え方です。","term":"2学期"},{"id":"h82","category":"history","unit":"幕末","difficulty":"standard","q":"「天皇を尊び、外国を排斥する」考えを何といいますか？","choices":["尊王攘夷","公武合体","殖産興業","富国強兵"],"answer":0,"a":"尊王攘夷は天皇を尊び、外国勢力を排斥する考えです。","term":"2学期"},{"id":"h83","category":"history","unit":"幕末","difficulty":"standard","q":"薩長同盟の成立に関わった土佐藩出身の人物は誰ですか？","choices":["坂本龍馬","西郷隆盛","大久保利通","木戸孝允"],"answer":0,"a":"坂本龍馬は薩長同盟の仲介などで活躍しました。","term":"2学期"},{"id":"h84","category":"history","unit":"幕末","difficulty":"standard","q":"大政奉還を行った最後の将軍は誰ですか？","choices":["徳川慶喜","徳川吉宗","徳川家光","徳川家康"],"answer":0,"a":"徳川慶喜が1867年に大政奉還を行いました。","term":"2学期"},{"id":"h85","category":"history","unit":"明治維新","difficulty":"basic","q":"明治政府が1868年に示した新政府の基本方針は何ですか？","choices":["五箇条の御誓文","武家諸法度","学制","地租改正"],"answer":0,"a":"五箇条の御誓文は新政府の政治の基本方針を示しました。","term":"3学期"},{"id":"h86","category":"history","unit":"明治維新","difficulty":"basic","q":"明治政府が藩を廃止して府県を置いたのは何年ですか？","choices":["1868年","1871年","1877年","1889年"],"answer":1,"a":"廃藩置県は1871年に行われました。","term":"3学期"},{"id":"h87","category":"history","unit":"明治維新","difficulty":"standard","q":"版籍奉還の内容として正しいのはどれですか？","choices":["藩主が土地と人民を朝廷に返した","藩を廃止した","徴兵を始めた","税を現金で納めさせた"],"answer":0,"a":"版籍奉還では藩主が版（土地）と籍（人民）を朝廷に返しました。","term":"3学期"},{"id":"h88","category":"history","unit":"明治維新","difficulty":"standard","q":"地租改正で土地所有者が納めた税は何を基準にしましたか？","choices":["地価","収穫量だけ","人口","家屋数"],"answer":0,"a":"地租改正では地価を基準に地租を課しました。","term":"3学期"},{"id":"h89","category":"history","unit":"明治維新","difficulty":"standard","q":"地租改正によって税を納める方法は主にどう変わりましたか？","choices":["米中心から現金中心へ","現金から米中心へ","税が完全になくなった","外国通貨だけになった"],"answer":0,"a":"地租は現金で納める制度になりました。","term":"3学期"},{"id":"h90","category":"history","unit":"明治維新","difficulty":"basic","q":"徴兵令が出されたのは何年ですか？","choices":["1871年","1873年","1877年","1885年"],"answer":1,"a":"徴兵令は1873年に出されました。","term":"3学期"},{"id":"h91","category":"history","unit":"明治維新","difficulty":"standard","q":"徴兵令によって兵役の対象となったのは主に誰ですか？","choices":["国民の男子","大名だけ","農民だけ","武士だけ"],"answer":0,"a":"徴兵令では満20歳以上の男子を中心に兵役を課しました。","term":"3学期"},{"id":"h92","category":"history","unit":"明治維新","difficulty":"basic","q":"明治政府が近代的な学校制度を定めた法令は何ですか？","choices":["学制","教育令","教育勅語","学校令"],"answer":0,"a":"1872年に学制が公布されました。","term":"3学期"},{"id":"h93","category":"history","unit":"明治維新","difficulty":"standard","q":"文明開化の象徴として広まった交通機関はどれですか？","choices":["鉄道","人力車だけ","馬車だけ","飛脚だけ"],"answer":0,"a":"文明開化の中で鉄道など近代的な交通が広がりました。","term":"3学期"},{"id":"h94","category":"history","unit":"明治維新","difficulty":"standard","q":"日本で最初の鉄道が開業した区間はどれですか？","choices":["新橋―横浜","大阪―神戸","東京―京都","函館―札幌"],"answer":0,"a":"1872年、新橋と横浜の間で鉄道が開業しました。","term":"3学期"},{"id":"h95","category":"history","unit":"明治維新","difficulty":"standard","q":"明治政府が官営模範工場として建設した代表的な製糸工場はどれですか？","choices":["富岡製糸場","八幡製鉄所","横須賀造船所だけ","三池炭鉱"],"answer":0,"a":"富岡製糸場は官営模範工場として1872年に設立されました。","term":"3学期"},{"id":"h96","category":"history","unit":"明治維新","difficulty":"advanced","q":"殖産興業の政策で政府が重視したものはどれですか？","choices":["近代産業の育成","封建的身分制の強化","鎖国の復活","寺子屋の廃止だけ"],"answer":0,"a":"殖産興業は近代産業を育成し国を豊かにすることをめざしました。","term":"3学期"},{"id":"h97","category":"history","unit":"明治維新","difficulty":"standard","q":"富国強兵の「強兵」と関係が深いものはどれですか？","choices":["軍事力の強化","農地改革","学校の廃止","貿易の停止"],"answer":0,"a":"富国強兵は経済力と軍事力を高めることをめざしました。","term":"3学期"},{"id":"h98","category":"history","unit":"明治維新","difficulty":"standard","q":"明治政府が国民に「四民平等」を進める中でなくなっていったものはどれですか？","choices":["身分制度","都道府県","学校","鉄道"],"answer":0,"a":"明治政府は旧来の身分制度を改め、身分による差別の撤廃を進めました。","term":"3学期"},{"id":"h99","category":"history","unit":"明治維新","difficulty":"basic","q":"1871年の廃藩置県によって進んだ政治の特徴はどれですか？","choices":["中央集権化","地方分権化だけ","鎖国","幕府政治の復活"],"answer":0,"a":"廃藩置県によって政府が全国を直接支配する中央集権化が進みました。","term":"3学期"},{"id":"h100","category":"history","unit":"明治維新","difficulty":"advanced","q":"明治政府が「文明開化」を進めた背景として適切なのはどれですか？","choices":["欧米の制度や文化を取り入れて近代化する必要があった","江戸文化を完全に禁止するためだけ","農業をなくすため","海外との交流を断つため"],"answer":0,"a":"欧米列強に対抗し近代国家をつくるため、制度や文化を取り入れました。","term":"3学期"},{"id":"h101","category":"history","unit":"明治維新","difficulty":"standard","q":"明治初期の「岩倉使節団」が訪問した地域は主にどこですか？","choices":["欧米諸国","アジア東南部だけ","北海道だけ","沖縄だけ"],"answer":0,"a":"岩倉使節団は欧米諸国を訪問し、制度や産業などを調査しました。","term":"3学期"},{"id":"h102","category":"history","unit":"明治維新","difficulty":"advanced","q":"岩倉使節団の目的の一つとして重要だったのはどれですか？","choices":["欧米の制度や産業を調査する","鎖国を進める","幕府を復活させる","大名を増やす"],"answer":0,"a":"欧米の制度や産業を調査し、日本の近代化に役立てることが目的の一つでした。","term":"3学期"},{"id":"h103","category":"history","unit":"明治維新","difficulty":"basic","q":"西洋式の服装やガス灯など、新しい生活様式が広がったことを何といいますか？","choices":["文明開化","鎖国","参勤交代","尊王攘夷"],"answer":0,"a":"西洋の文化や生活様式が取り入れられたことを文明開化といいます。","term":"3学期"},{"id":"h104","category":"history","unit":"明治維新","difficulty":"standard","q":"明治初期に発行された新聞が広がった背景として適切なのはどれですか？","choices":["活版印刷や教育の普及","鎖国の強化","寺子屋の消滅だけ","農業の機械化だけ"],"answer":0,"a":"印刷技術や識字率の向上などを背景に新聞が普及しました。","term":"3学期"},{"id":"h105","category":"history","unit":"明治維新","difficulty":"advanced","q":"明治政府が中央集権化を進めた結果として整えられたものはどれですか？","choices":["全国を府県に分ける行政制度","大名による独立統治","鎖国の再開","参勤交代"],"answer":0,"a":"廃藩置県後、府県を通じて中央政府が全国を統治しました。","term":"3学期"},{"id":"h106","category":"history","unit":"明治維新","difficulty":"standard","q":"地租改正の結果、政府の税収が安定しやすくなった理由として適切なのはどれですか？","choices":["現金で納める土地税にしたため","収穫がなくても税を免除したため","税そのものをなくしたため","外国から税を受け取ったため"],"answer":0,"a":"地租を現金で納める制度にし、政府の歳入を安定させようとしました。","term":"3学期"},{"id":"h107","category":"history","unit":"明治維新","difficulty":"advanced","q":"明治初期の自由民権運動が政府に求めたものとして代表的なのはどれですか？","choices":["国会開設など政治参加の拡大","鎖国の復活","参勤交代の再開","身分制度の復活"],"answer":0,"a":"自由民権運動では国会開設や人民の権利を求める声が高まりました。","term":"3学期"},{"id":"h108","category":"history","unit":"明治維新","difficulty":"standard","q":"1874年に「民撰議院設立建白書」を提出した人物は誰ですか？","choices":["板垣退助ら","徳川慶喜ら","西郷隆盛ら","伊藤博文ら"],"answer":0,"a":"板垣退助らが民撰議院設立建白書を提出しました。","term":"3学期"},{"id":"h109","category":"history","unit":"明治維新","difficulty":"standard","q":"1881年、政府が国会を開く方針を示したものは何ですか？","choices":["国会開設の勅諭","五箇条の御誓文","教育勅語","廃藩置県"],"answer":0,"a":"1881年、国会開設の勅諭が出されました。","term":"3学期"},{"id":"h110","category":"history","unit":"明治維新","difficulty":"basic","q":"1889年に発布された憲法は何ですか？","choices":["大日本帝国憲法","日本国憲法","五箇条の御誓文","教育基本法"],"answer":0,"a":"1889年に大日本帝国憲法が発布されました。","term":"3学期"},{"id":"h111","category":"history","unit":"明治維新","difficulty":"standard","q":"大日本帝国憲法で主権者とされたのは誰ですか？","choices":["天皇","国民","内閣総理大臣","衆議院"],"answer":0,"a":"大日本帝国憲法では天皇主権とされました。","term":"3学期"},{"id":"h112","category":"history","unit":"明治維新","difficulty":"standard","q":"1890年に開設された日本の議会は何と呼ばれますか？","choices":["帝国議会","国会議院","民会","府県会"],"answer":0,"a":"1890年に帝国議会が開設されました。","term":"3学期"},{"id":"h113","category":"history","unit":"明治維新","difficulty":"advanced","q":"明治政府が不平等条約の改正を急いだ背景はどれですか？","choices":["近代国家として欧米諸国と対等な関係を築くため","鎖国を復活させるため","税をなくすため","藩を復活させるため"],"answer":0,"a":"近代国家として認められ、条約上の不平等を解消することが目標でした。","term":"3学期"},{"id":"h114","category":"history","unit":"明治維新","difficulty":"standard","q":"明治時代に急速に発展した紡績業と関係が深い原料はどれですか？","choices":["綿花","石炭だけ","木材だけ","鉄鉱石だけ"],"answer":0,"a":"紡績業では綿花を原料として糸や綿製品をつくりました。","term":"3学期"},{"id":"h115","category":"history","unit":"明治維新","difficulty":"advanced","q":"明治時代の近代化を進める一方で、農民などの負担になった改革の例はどれですか？","choices":["地租改正","学制の公布だけ","鉄道開業だけ","文明開化だけ"],"answer":0,"a":"地租改正では税負担をめぐって農民の不満が高まることもありました。","term":"3学期"},{"id":"c26","category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法が施行されたのは何年ですか？","choices":["1945年","1946年","1947年","1950年"],"answer":2,"a":"日本国憲法は1946年11月3日に公布され、1947年5月3日に施行されました。","term":"3学期"},{"id":"c27","category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法の基本原理に含まれないものはどれですか？","choices":["国民主権","基本的人権の尊重","平和主義","身分制度"],"answer":3,"a":"身分制度は日本国憲法の基本原理ではありません。","term":"3学期"},{"id":"c28","category":"civics","unit":"日本国憲法","difficulty":"standard","q":"国民主権とはどのような考え方ですか？","choices":["政治の最終的な決定権が国民にある","裁判官が法律を作る","地方議会が国会を解散する","内閣が国民を任命する"],"answer":0,"a":"国民主権は政治のあり方を最終的に決める力が国民にあるという考えです。","term":"3学期"},{"id":"c29","category":"civics","unit":"日本国憲法","difficulty":"standard","q":"日本国憲法の公布日は何月何日ですか？","choices":["5月3日","11月3日","2月11日","4月1日"],"answer":1,"a":"日本国憲法は1946年11月3日に公布されました。","term":"3学期"},{"id":"c30","category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法の施行日は何月何日ですか？","choices":["5月3日","11月3日","8月15日","12月23日"],"answer":0,"a":"日本国憲法は1947年5月3日に施行されました。","term":"3学期"},{"id":"c31","category":"civics","unit":"基本的人権","difficulty":"basic","q":"思想・良心の自由は何の権利に分類されますか？","choices":["自由権","社会権","参政権","請求権"],"answer":0,"a":"思想・良心の自由は自由権に含まれます。","term":"3学期"},{"id":"c32","category":"civics","unit":"基本的人権","difficulty":"standard","q":"職業選択の自由は何の権利ですか？","choices":["自由権","社会権","参政権","受益権"],"answer":0,"a":"職業選択の自由は自由権の一つです。","term":"3学期"},{"id":"c33","category":"civics","unit":"基本的人権","difficulty":"standard","q":"生存権を定めている日本国憲法の条文は何条ですか？","choices":["13条","25条","26条","27条"],"answer":1,"a":"憲法25条は健康で文化的な最低限度の生活を営む権利を定めています。","term":"3学期"},{"id":"c34","category":"civics","unit":"基本的人権","difficulty":"basic","q":"教育を受ける権利と関係する憲法上の権利はどれですか？","choices":["26条","9条","15条","41条"],"answer":0,"a":"憲法26条は教育を受ける権利などを定めています。","term":"3学期"},{"id":"c35","category":"civics","unit":"基本的人権","difficulty":"standard","q":"労働基本権に含まれないものはどれですか？","choices":["団結権","団体交渉権","団体行動権","財産権"],"answer":3,"a":"団結権・団体交渉権・団体行動権が労働基本権です。","term":"3学期"},{"id":"c36","category":"civics","unit":"基本的人権","difficulty":"standard","q":"男女共同参画と特に関係が深い人権はどれですか？","choices":["法の下の平等","信教の自由","職業選択だけ","請願権だけ"],"answer":0,"a":"男女が性別にかかわらず平等に扱われることは法の下の平等と関係します。","term":"3学期"},{"id":"c37","category":"civics","unit":"基本的人権","difficulty":"advanced","q":"人権と人権が衝突する場合に調整を図る考え方として知られるものはどれですか？","choices":["公共の福祉","参勤交代","三権分立","地方自治"],"answer":0,"a":"他者の人権との調整などのため、公共の福祉という考え方が用いられます。","term":"3学期"},{"id":"c38","category":"civics","unit":"基本的人権","difficulty":"basic","q":"裁判を受ける権利などは何の権利に分類されますか？","choices":["請求権","自由権","社会権","参政権"],"answer":0,"a":"請求権には裁判を受ける権利などが含まれます。","term":"3学期"},{"id":"c39","category":"civics","unit":"基本的人権","difficulty":"standard","q":"国務請求権に当たるものはどれですか？","choices":["裁判を受ける権利","信教の自由","選挙権","生存権"],"answer":0,"a":"裁判を受ける権利などは国家に一定の行為を求める請求権です。","term":"3学期"},{"id":"c40","category":"civics","unit":"基本的人権","difficulty":"standard","q":"選挙権はどのような権利ですか？","choices":["参政権","社会権","自由権","請求権"],"answer":0,"a":"選挙権は政治に参加するための参政権です。","term":"3学期"},{"id":"c41","category":"civics","unit":"基本的人権","difficulty":"basic","q":"表現の自由に含まれるものはどれですか？","choices":["言論・出版などの自由","納税義務","教育を受ける義務","兵役義務"],"answer":0,"a":"言論・出版などの自由は表現の自由に含まれます。","term":"3学期"},{"id":"c42","category":"civics","unit":"国会","difficulty":"basic","q":"国会が担当する権力は何ですか？","choices":["立法権","行政権","司法権","地方自治権"],"answer":0,"a":"国会は立法権を担当します。","term":"3学期"},{"id":"c43","category":"civics","unit":"国会","difficulty":"standard","q":"予算を先に審議するのはどちらの議院ですか？","choices":["衆議院","参議院","両議院が同時","裁判所"],"answer":0,"a":"予算については衆議院の優越が認められ、衆議院で先に審議されます。","term":"3学期"},{"id":"c44","category":"civics","unit":"国会","difficulty":"standard","q":"法律案について衆議院で3分の2以上の賛成があれば再可決できることがあるのは、どの議院が否決した場合ですか？","choices":["参議院","衆議院","地方議会","最高裁判所"],"answer":0,"a":"参議院が否決した法律案は、条件を満たせば衆議院の3分の2以上で再可決できます。","term":"3学期"},{"id":"c45","category":"civics","unit":"国会","difficulty":"basic","q":"国会議員のうち、衆議院議員の任期は何年ですか？","choices":["4年","6年","5年","3年"],"answer":0,"a":"衆議院議員の任期は4年です。ただし、解散があればその時点で終了します。","term":"3学期"},{"id":"c46","category":"civics","unit":"国会","difficulty":"basic","q":"参議院議員の任期は何年ですか？","choices":["4年","6年","3年","8年"],"answer":1,"a":"参議院議員の任期は6年で、3年ごとに半数が改選されます。","term":"3学期"},{"id":"c47","category":"civics","unit":"国会","difficulty":"standard","q":"衆議院を解散できるのは何ですか？","choices":["内閣","最高裁判所","参議院","都道府県知事"],"answer":0,"a":"衆議院の解散は内閣が決定し、天皇が国事行為として行います。","term":"3学期"},{"id":"c48","category":"civics","unit":"国会","difficulty":"standard","q":"国会が内閣総理大臣を指名する仕組みと関係が深いものはどれですか？","choices":["議院内閣制","大統領制","直接民主制","君主制"],"answer":0,"a":"日本は議院内閣制で、国会が内閣総理大臣を指名します。","term":"3学期"},{"id":"c49","category":"civics","unit":"国会","difficulty":"advanced","q":"衆議院の優越が認められている理由として適切なのはどれですか？","choices":["任期が短く解散もあり、民意をより反映しやすいと考えられているため","議員数が少ないため","裁判所だから","地方議会だから"],"answer":0,"a":"衆議院は任期が短く解散もあるため、より民意を反映しやすいとされ、一定の事項で優越があります。","term":"3学期"},{"id":"c50","category":"civics","unit":"国会","difficulty":"standard","q":"国会の会議を公開する原則に例外を設けられるのはどのような場合ですか？","choices":["各議院が出席議員の3分の2以上の多数で非公開と決定した場合","首相が一人で決めた場合","裁判官が決めた場合","知事が決めた場合"],"answer":0,"a":"憲法では一定の条件で秘密会を開くことが認められています。","term":"3学期"},{"id":"c51","category":"civics","unit":"内閣","difficulty":"basic","q":"内閣が担当する権力は何ですか？","choices":["行政権","立法権","司法権","監査権"],"answer":0,"a":"内閣は行政権を担当します。","term":"3学期"},{"id":"c52","category":"civics","unit":"内閣","difficulty":"standard","q":"国務大臣の過半数は何でなければなりませんか？","choices":["国会議員","裁判官","地方議員","公務員でない人"],"answer":0,"a":"国務大臣の過半数は国会議員でなければなりません。","term":"3学期"},{"id":"c53","category":"civics","unit":"内閣","difficulty":"basic","q":"内閣総理大臣は誰から任命されますか？","choices":["天皇","国会議長","最高裁判所長官","都道府県知事"],"answer":0,"a":"内閣総理大臣は国会の指名に基づいて天皇が任命します。","term":"3学期"},{"id":"c54","category":"civics","unit":"内閣","difficulty":"standard","q":"内閣が法律を実施するために定めるものは何ですか？","choices":["政令","条例","判決","憲章"],"answer":0,"a":"内閣は法律の範囲内で政令を制定できます。","term":"3学期"},{"id":"c55","category":"civics","unit":"内閣","difficulty":"standard","q":"内閣が衆議院を解散した後、総選挙は何日以内に行われますか？","choices":["40日以内","30日以内","60日以内","90日以内"],"answer":0,"a":"衆議院解散後は40日以内に総選挙を行います。","term":"3学期"},{"id":"c56","category":"civics","unit":"内閣","difficulty":"advanced","q":"内閣が総辞職しなければならないのはどのような場合ですか？","choices":["衆議院で内閣不信任決議が可決され、10日以内に衆議院を解散しない場合","参議院議員が一人辞職した場合","最高裁が一つの判決を出した場合","地方議会が議決した場合"],"answer":0,"a":"憲法69条により、この場合内閣は総辞職します。","term":"3学期"},{"id":"c57","category":"civics","unit":"裁判所","difficulty":"basic","q":"裁判所が担当する権力は何ですか？","choices":["司法権","行政権","立法権","予算権"],"answer":0,"a":"裁判所は司法権を担当します。","term":"3学期"},{"id":"c58","category":"civics","unit":"裁判所","difficulty":"standard","q":"日本の裁判所が法令などが憲法に適合するか判断する権限を何といいますか？","choices":["違憲審査権","行政監督権","立法権","外交権"],"answer":0,"a":"裁判所には法令などの合憲性を判断する違憲審査権があります。","term":"3学期"},{"id":"c59","category":"civics","unit":"裁判所","difficulty":"basic","q":"最高裁判所の長を何といいますか？","choices":["最高裁判所長官","国会議長","内閣官房長官","法務大臣"],"answer":0,"a":"最高裁判所の長は最高裁判所長官です。","term":"3学期"},{"id":"c60","category":"civics","unit":"裁判所","difficulty":"standard","q":"三審制の目的として適切なのはどれですか？","choices":["裁判を複数の段階で審理し、誤判を防ぐ機会を確保する","裁判を必ず3日に終える","裁判官を3人にする","法律を3本にする"],"answer":0,"a":"三審制は上級裁判所で審理をやり直す機会を保障し、慎重な裁判を行うためです。","term":"3学期"},{"id":"c61","category":"civics","unit":"裁判所","difficulty":"standard","q":"第一審を担当する裁判所として代表的なのはどれですか？","choices":["地方裁判所","最高裁判所","簡易裁判所だけ","国会"],"answer":0,"a":"地方裁判所などが第一審を担当します。事件によっては簡易裁判所や家庭裁判所が第一審になることもあります。","term":"3学期"},{"id":"c62","category":"civics","unit":"裁判所","difficulty":"advanced","q":"国民が刑事裁判に参加する裁判員制度の対象となるのは主にどのような事件ですか？","choices":["重大な刑事事件","すべての民事事件","離婚事件だけ","地方税の事件だけ"],"answer":0,"a":"裁判員制度は重大な刑事事件の第一審で行われます。","term":"3学期"},{"id":"c63","category":"civics","unit":"地方自治","difficulty":"basic","q":"地方公共団体が制定するルールを何といいますか？","choices":["条例","法律","政令","判例"],"answer":0,"a":"地方公共団体が定めるルールを条例といいます。","term":"3学期"},{"id":"c64","category":"civics","unit":"地方自治","difficulty":"basic","q":"都道府県の長を何といいますか？","choices":["知事","市長","町長","首長議長"],"answer":0,"a":"都道府県の長は知事です。","term":"3学期"},{"id":"c65","category":"civics","unit":"地方自治","difficulty":"standard","q":"市区町村の長を何といいますか？","choices":["市町村長（首長）","知事","国務大臣","裁判官"],"answer":0,"a":"市区町村の長を市町村長といい、首長の一種です。","term":"3学期"},{"id":"c66","category":"civics","unit":"地方自治","difficulty":"standard","q":"地方自治で、住民が直接請求できる制度と関係が深いものはどれですか？","choices":["住民投票や条例制定・改廃請求など","参勤交代","大政奉還","五箇条の御誓文"],"answer":0,"a":"地方自治には、住民が条例の制定・改廃などを直接請求できる制度があります。","term":"3学期"},{"id":"c67","category":"civics","unit":"地方自治","difficulty":"advanced","q":"地方自治の「二元代表制」とは何と何を住民が選ぶ仕組みですか？","choices":["首長と地方議会議員","国会議員と裁判官","内閣総理大臣と知事","議員と天皇"],"answer":0,"a":"住民が首長と地方議会議員をそれぞれ直接選挙します。","term":"3学期"},{"id":"c68","category":"civics","unit":"地方自治","difficulty":"standard","q":"地方公共団体の仕事の財源として中心となるものの一つはどれですか？","choices":["地方税","関税だけ","国債だけ","寄付金だけ"],"answer":0,"a":"地方公共団体は地方税などを主な財源として行政を行います。","term":"3学期"},{"id":"c69","category":"civics","unit":"地方自治","difficulty":"standard","q":"国から地方公共団体へ配分され、地域間の財政力格差を調整する役割があるものはどれですか？","choices":["地方交付税交付金","関税","印紙税","株式配当"],"answer":0,"a":"地方交付税交付金は地域間の財政力格差を調整する役割があります。","term":"3学期"},{"id":"c70","category":"civics","unit":"選挙","difficulty":"basic","q":"公職選挙法に基づく国政選挙で、満18歳以上の日本国民が持つのは何ですか？","choices":["選挙権","被選挙権すべて","裁判員資格","国務大臣任命権"],"answer":0,"a":"日本では2016年から国政選挙の選挙権年齢が18歳に引き下げられました。","term":"3学期"},{"id":"c71","category":"civics","unit":"選挙","difficulty":"standard","q":"選挙区から一人の候補者を選ぶ方式は何ですか？","choices":["小選挙区制","比例代表制","大選挙区制","直接民主制"],"answer":0,"a":"小選挙区制では、各選挙区から原則として1人の当選者を選びます。","term":"3学期"},{"id":"c72","category":"civics","unit":"選挙","difficulty":"standard","q":"政党などに投票し、得票数に応じて議席を配分する方式は何ですか？","choices":["比例代表制","小選挙区制","世襲制","任命制"],"answer":0,"a":"比例代表制では得票に応じて議席が配分されます。","term":"3学期"},{"id":"c73","category":"civics","unit":"選挙","difficulty":"basic","q":"「誰に投票したかを知られない」原則は何ですか？","choices":["秘密選挙","平等選挙","普通選挙","直接選挙"],"answer":0,"a":"秘密選挙は投票内容を他人に知られないようにする原則です。","term":"3学期"},{"id":"c74","category":"civics","unit":"選挙","difficulty":"basic","q":"一定の年齢以上の国民に広く選挙権を認める考えを何といいますか？","choices":["普通選挙","制限選挙","記名選挙","間接選挙"],"answer":0,"a":"普通選挙は財産や身分などによる制限を設けず、一定の年齢などの条件で広く選挙権を認める考えです。","term":"3学期"},{"id":"c75","category":"civics","unit":"選挙","difficulty":"standard","q":"候補者の名前ではなく政党名などを書く投票の特徴を持つのはどれですか？","choices":["比例代表選挙","小選挙区選挙だけ","首長選挙だけ","裁判員制度"],"answer":0,"a":"比例代表選挙では政党名などを記入して議席を配分する方式があります。","term":"3学期"},{"id":"c76","category":"civics","unit":"現代社会","difficulty":"basic","q":"現代社会で、多くの人がインターネットを通して情報を得たり発信したりする社会を何と表現できますか？","choices":["情報社会","農業社会","封建社会","鎖国社会"],"answer":0,"a":"情報通信技術が社会生活に大きな影響を与える社会を情報社会と呼びます。","term":"3学期"},{"id":"c77","category":"civics","unit":"現代社会","difficulty":"standard","q":"インターネット上の情報を判断するときに確認すべきものとして適切なのはどれですか？","choices":["発信者・根拠・更新時期など","文字の大きさだけ","写真の色だけ","広告の有無だけ"],"answer":0,"a":"情報の信頼性を考えるには、発信者や根拠、更新時期などを確認します。","term":"3学期"},{"id":"c78","category":"civics","unit":"現代社会","difficulty":"standard","q":"著作権で保護される対象に含まれるものはどれですか？","choices":["創作した文章や音楽など","自然現象そのもの","数学の単純な計算結果だけ","誰でも使える信号"],"answer":0,"a":"創作性のある文章・音楽・画像などは著作物として保護されます。","term":"3学期"},{"id":"c79","category":"civics","unit":"消費生活","difficulty":"basic","q":"消費者が商品を選ぶときに確認するものとして適切なのはどれですか？","choices":["価格・品質・安全性など","広告の派手さだけ","店の大きさだけ","店員の服装だけ"],"answer":0,"a":"価格だけでなく品質や安全性、必要性などを確認して選ぶことが重要です。","term":"3学期"},{"id":"c80","category":"civics","unit":"消費生活","difficulty":"standard","q":"消費者トラブルについて相談する代表的な窓口はどれですか？","choices":["消費生活センター","税務署だけ","裁判所だけ","図書館"],"answer":0,"a":"消費生活センターでは消費者トラブルについて相談できます。","term":"3学期"},{"id":"c81","category":"civics","unit":"消費生活","difficulty":"standard","q":"クーリング・オフが認められる主な目的は何ですか？","choices":["一定の取引で消費者が冷静に契約を見直す機会を確保する","すべての商品を無料にする","税金をなくす","裁判を不要にする"],"answer":0,"a":"特定の取引では一定期間、無条件で契約を解除できるクーリング・オフ制度があります。","term":"3学期"},{"id":"c82","category":"civics","unit":"消費生活","difficulty":"advanced","q":"契約が成立すると原則としてどのような効果がありますか？","choices":["当事者に権利や義務が生じる","必ず現金しか使えなくなる","契約書がなくても全て無効になる","政府が自動的に契約を変更する"],"answer":0,"a":"契約は原則として当事者の合意で成立し、権利・義務が生じます。","term":"3学期"},{"id":"c83","category":"civics","unit":"消費生活","difficulty":"standard","q":"未成年者の契約で特に注意が必要なことはどれですか？","choices":["原則として法定代理人の同意が必要な場合がある","どんな契約でも自由に取り消せない","契約はすべて自動的に無効","現金契約しかできない"],"answer":0,"a":"未成年者は一定の場合、法定代理人の同意なくした法律行為を取り消せる制度があります。","term":"3学期"},{"id":"c84","category":"civics","unit":"日本国憲法","difficulty":"advanced","q":"国会・内閣・裁判所が互いに抑制し合うことで、権力の集中を防ぐ考えはどれですか？","choices":["三権分立","地方自治","普通選挙","社会権"],"answer":0,"a":"立法・行政・司法を分け、互いに抑制と均衡を図るのが三権分立です。","term":"3学期"},{"id":"c85","category":"civics","unit":"日本国憲法","difficulty":"standard","q":"日本国憲法で国事行為を行う天皇が「象徴」とされることと関係が深いのはどれですか？","choices":["主権が国民にあること","天皇が政治の最高権力者であること","国会が裁判を行うこと","地方自治の廃止"],"answer":0,"a":"日本国憲法では主権は国民にあり、天皇は日本国と日本国民統合の象徴とされています。","term":"3学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の8地方区分で、東北地方の南に位置する地方はどれですか？","choices":["北海道地方","関東地方","中部地方","中国地方"],"answer":1,"a":"東北地方の南には関東地方があります。","id":"n301","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"関東地方に含まれる都県はどれですか？","choices":["新潟県","長野県","東京都","福井県"],"answer":2,"a":"東京都は関東地方に含まれます。","id":"n302","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"中部地方をさらに3つに分ける呼び方として適切なのはどれですか？","choices":["東海・中央高地・北陸","山陰・山陽・四国","関東・東北・北海道","近畿・中国・九州"],"answer":0,"a":"中部地方は東海、中央高地、北陸の3地域に分けて考えることがあります。","id":"n303","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"近畿地方に含まれる府県はどれですか？","choices":["大阪府","宮城県","香川県","福岡県"],"answer":0,"a":"大阪府は近畿地方に含まれます。","id":"n304","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"山陰地方に含まれる県はどれですか？","choices":["鳥取県","岡山県","広島県","山口県"],"answer":0,"a":"山陰地方には鳥取県と島根県があります。","id":"n305","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"瀬戸内海に面する県を含む地域として代表的なものはどれですか？","choices":["中国・四国地方","北海道地方","東北地方","九州南部だけ"],"answer":0,"a":"瀬戸内海沿岸には中国・四国・近畿・九州の一部が位置します。","id":"n306","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"九州地方で県庁所在地が福岡市である県はどこですか？","choices":["福岡県","佐賀県","熊本県","大分県"],"answer":0,"a":"福岡県の県庁所在地は福岡市です。","id":"n307","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"四国地方を構成する4県に含まれないものはどれですか？","choices":["徳島県","香川県","高知県","宮崎県"],"answer":3,"a":"四国4県は徳島・香川・愛媛・高知です。","id":"n308","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"本州と四国の間にある海はどれですか？","choices":["瀬戸内海","日本海","オホーツク海","東シナ海"],"answer":0,"a":"本州と四国の間には瀬戸内海があります。","id":"n309","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"advanced","q":"日本が海に囲まれた国であることが、産業に与える影響として適切なのはどれですか？","choices":["水産業や海上交通が発達しやすい","農業ができない","工業が成立しない","河川がなくなる"],"answer":0,"a":"四方を海に囲まれているため、水産業や海上交通が重要です。","id":"n310","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"basic","q":"日本の国土の東側・南側に広がる大洋はどれですか？","choices":["太平洋","大西洋","インド洋","北極海"],"answer":0,"a":"日本の東側から南側には太平洋が広がっています。","id":"n311","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"北海道と本州の間にある海峡はどれですか？","choices":["津軽海峡","関門海峡","鳴門海峡","豊後水道"],"answer":0,"a":"北海道と本州の間には津軽海峡があります。","id":"n312","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"standard","q":"本州と九州の間にある代表的な海峡はどれですか？","choices":["関門海峡","津軽海峡","宗谷海峡","明石海峡"],"answer":0,"a":"本州と九州の間には関門海峡があります。","id":"n313","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"advanced","q":"日本の領海の基準となる基線から原則12海里までの海域を何といいますか？","choices":["領海","排他的経済水域","公海","接続水域"],"answer":0,"a":"領海は基線から原則12海里までの海域です。","id":"n314","term":"1学期"},{"category":"geography","unit":"日本の地域構成","difficulty":"advanced","q":"水産資源や海底資源などについて沿岸国の権利が認められる、沿岸から200海里までの海域を何といいますか？","choices":["領海","排他的経済水域","公海","内水"],"answer":1,"a":"排他的経済水域（EEZ）は原則として沿岸から200海里までです。","id":"n315","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"basic","q":"人口が都市部へ移動することを何といいますか？","choices":["人口移動","地形変化","季節風","植林"],"answer":0,"a":"人口移動は人々が住む場所を移すことです。","id":"n316","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"standard","q":"大都市の周辺部に住宅地が広がる現象を表す語として適切なのはどれですか？","choices":["郊外化","過疎化","高齢化","工業化"],"answer":0,"a":"都市の周辺部に住宅地などが拡大する現象を郊外化といいます。","id":"n317","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"standard","q":"少子化とは、一般に何が低下することを指しますか？","choices":["出生数や出生率","平均寿命","識字率","就業者数だけ"],"answer":0,"a":"少子化は出生数や出生率の低下などによって子どもの割合が減ることです。","id":"n318","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"advanced","q":"地方で若い世代が都市へ流出すると、地域で起こりやすい問題はどれですか？","choices":["人口減少と高齢化","人口の急増","農地の無限拡大","気温の低下"],"answer":0,"a":"若年層の流出は人口減少・高齢化や担い手不足につながることがあります。","id":"n319","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"standard","q":"人口密度は何を表す指標ですか？","choices":["面積あたりの人口","1人あたりの所得","年齢別人口の割合","出生数"],"answer":0,"a":"人口密度は一定の面積あたりに何人住んでいるかを示します。","id":"n320","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"standard","q":"昼間人口が夜間人口より多くなりやすい都市の特徴はどれですか？","choices":["通勤・通学で人が流入する中心都市","人口流出が続く農村","無人島","工場がない地域"],"answer":0,"a":"昼間に周辺から通勤・通学者が流入する都市では昼間人口が多くなります。","id":"n321","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"advanced","q":"人口を年齢構成で区分すると、一般に年少人口は何歳未満ですか？","choices":["15歳未満","18歳未満","20歳未満","25歳未満"],"answer":0,"a":"人口統計では年少人口を15歳未満、生産年齢人口を15～64歳、老年人口を65歳以上とする区分がよく使われます。","id":"n322","term":"1学期"},{"category":"geography","unit":"人口","difficulty":"basic","q":"人がほとんど住んでいない過疎地域で、公共交通の維持が難しくなる一因はどれですか？","choices":["利用者の減少","人口の急増","道路の増加","観光客の増加"],"answer":0,"a":"人口が減ると公共交通の利用者も減少し、路線維持が難しくなる場合があります。","id":"n323","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"basic","q":"米を主に栽培する農業を何といいますか？","choices":["稲作","酪農","養蚕","畜産加工"],"answer":0,"a":"米を栽培する農業を稲作といいます。","id":"n324","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"basic","q":"乳牛を飼育して牛乳を生産する農業はどれですか？","choices":["酪農","養豚","養蚕","果樹栽培"],"answer":0,"a":"酪農は乳牛を飼育して牛乳などを生産します。","id":"n325","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"北海道で盛んな酪農に適した条件として適切なのはどれですか？","choices":["広い牧草地を確保しやすい","温泉が多い","人口密度が高い","年間降水量が極端に少ない"],"answer":0,"a":"北海道では広い土地を利用して大規模な酪農が行われています。","id":"n326","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"甲府盆地などで盛んな農業として代表的なものはどれですか？","choices":["果樹栽培","サトウキビ栽培","大規模酪農","茶だけの栽培"],"answer":0,"a":"甲府盆地はぶどうやももなどの果樹栽培で知られています。","id":"n327","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"静岡県で生産が盛んな農産物として代表的なものはどれですか？","choices":["茶","てんさい","小麦だけ","りんごだけ"],"answer":0,"a":"静岡県は茶の生産が盛んな地域として知られています。","id":"n328","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"沖縄県など温暖な地域で栽培が盛んな作物はどれですか？","choices":["さとうきび","てんさい","りんご","じゃがいも"],"answer":0,"a":"沖縄県では温暖な気候を利用してさとうきびが栽培されています。","id":"n329","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"advanced","q":"農産物を産地から消費地へ運ぶ際に、冷蔵・冷凍設備などを利用する輸送を何と関連づけて考えますか？","choices":["コールドチェーン","参勤交代","都市計画","輪作"],"answer":0,"a":"コールドチェーンは温度管理を保ちながら食品などを流通させる仕組みです。","id":"n330","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"工場が海外へ移転することによって国内の工業生産が減少する現象に関連する語はどれですか？","choices":["産業の空洞化","過密化","促成栽培","少子化"],"answer":0,"a":"産業の空洞化は、工場などの海外移転により国内の産業基盤が弱まる現象を指します。","id":"n331","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"basic","q":"自動車工業が盛んな工業地域として知られる地域はどれですか？","choices":["中京工業地帯","北陸工業地域","京葉工業地域","瀬戸内工業地域"],"answer":0,"a":"愛知県を中心とする中京工業地帯は自動車工業が盛んです。","id":"n332","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"石油化学コンビナートが発達しやすい立地はどれですか？","choices":["臨海部","山頂","盆地の奥地だけ","高原の中心"],"answer":0,"a":"原料の輸入や製品の輸送に便利な臨海部には石油化学工業などが立地します。","id":"n333","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"高速道路や新幹線などの交通網が発達すると、地域に起こりやすい変化はどれですか？","choices":["人や物の移動が活発になる","必ず人口がゼロになる","農業ができなくなる","降水量が増える"],"answer":0,"a":"交通網の発達は人や物の移動、地域間の結びつきを強めます。","id":"n334","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"advanced","q":"情報通信技術の発達により、工場を一か所に集中させなくても仕事を進めやすくなることと関係が深いのはどれですか？","choices":["テレワークや遠隔業務","参勤交代","焼畑農業","灌漑農業"],"answer":0,"a":"ICTの発達は遠隔地との情報交換やテレワークを可能にします。","id":"n335","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"養殖業とはどのような水産業ですか？","choices":["魚や貝などを人が管理して育てる","魚をすべて輸入する","河川を埋め立てる","海水を淡水にする"],"answer":0,"a":"養殖業は魚・貝・海藻などを人が管理して育てます。","id":"n336","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"basic","q":"漁業のうち、沿岸近くで行う比較的小規模な漁業を何といいますか？","choices":["沿岸漁業","遠洋漁業","捕鯨漁業","内陸漁業"],"answer":0,"a":"沿岸漁業は沿岸近くで行われます。","id":"n337","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"advanced","q":"観光客が地域を訪れることで生まれる収入や雇用を地域の産業振興に活用することを何と関連づけて考えますか？","choices":["観光振興","工場閉鎖","過疎化","輸入制限"],"answer":0,"a":"観光振興は観光資源を活用して地域経済の活性化を目指します。","id":"n338","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"コンビニエンスストアなどの小売業は何次産業に分類されますか？","choices":["第一次産業","第二次産業","第三次産業","第四次産業"],"answer":2,"a":"小売業はサービス業などと同じ第三次産業です。","id":"n339","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"製造業で原料を加工して製品をつくる活動は何次産業ですか？","choices":["第一次産業","第二次産業","第三次産業","第五次産業"],"answer":1,"a":"製造業は第二次産業に含まれます。","id":"n340","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"basic","q":"林業は何次産業ですか？","choices":["第一次産業","第二次産業","第三次産業","第六次産業"],"answer":0,"a":"林業は自然から資源を採取する第一次産業です。","id":"n341","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"advanced","q":"農業と食品加工、販売などを組み合わせて付加価値を高める取り組みを表す言葉はどれですか？","choices":["六次産業化","工業地帯化","過密化","都市化"],"answer":0,"a":"六次産業化は一次・二次・三次産業を組み合わせて農林漁業者の所得向上などを目指す取り組みです。","id":"n342","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"standard","q":"高速道路のインターチェンジ周辺に物流施設が集まる理由として適切なのはどれですか？","choices":["輸送しやすいから","標高が高いから","人口が必ず少ないから","雪が多いから"],"answer":0,"a":"高速道路へのアクセスがよい場所は物流拠点として利用しやすいです。","id":"n343","term":"1学期"},{"category":"geography","unit":"産業","difficulty":"advanced","q":"大都市近郊で収穫後すぐに出荷したい農産物の栽培が行われやすい理由はどれですか？","choices":["消費地までの距離が短いから","雪が多いから","海流がないから","人口がゼロだから"],"answer":0,"a":"都市近郊は消費地に近く、新鮮な農産物を短時間で届けやすいです。","id":"n344","term":"1学期"},{"category":"geography","unit":"気候","difficulty":"basic","q":"日本の冬に大陸から吹く冷たい季節風はどちらですか？","choices":["北西の季節風","南東の季節風","北東の季節風だけ","西南西の季節風"],"answer":0,"a":"冬は大陸から北西の季節風が吹きます。","id":"n345","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"standard","q":"日本海側で冬に雪が多くなる仕組みとして適切なのはどれですか？","choices":["季節風が日本海から水蒸気を含むため","太平洋から乾いた風が吹くため","赤道に近いため","海流が消えるため"],"answer":0,"a":"北西の季節風が日本海で水蒸気を含み、山地で雪を降らせます。","id":"n346","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"standard","q":"太平洋側で冬に晴天が多い地域がある理由に関係が深いのはどれですか？","choices":["山地を越えた乾いた季節風","梅雨前線の停滞","台風だけ","やませだけ"],"answer":0,"a":"日本海側で雪を降らせた後の乾いた空気が山地を越えて太平洋側へ流れます。","id":"n347","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"standard","q":"梅雨の時期に日本付近で停滞しやすい前線は何ですか？","choices":["梅雨前線","寒冷前線だけ","閉塞前線だけ","無前線"],"answer":0,"a":"梅雨前線は北の冷たい空気と南の暖かく湿った空気の境界で停滞しやすい前線です。","id":"n348","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"advanced","q":"台風が日本へ近づくとき、特に注意が必要な災害の組み合わせはどれですか？","choices":["大雨・強風・高潮など","干ばつだけ","火山だけ","雪崩だけ"],"answer":0,"a":"台風は大雨、強風、高潮、高波など複数の災害を引き起こすことがあります。","id":"n349","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"basic","q":"沖縄・奄美の気候の特徴として適切なのはどれですか？","choices":["年間を通して温暖で台風の影響を受けやすい","冬に豪雪が続く","年中乾燥している","日較差が極端に大きい"],"answer":0,"a":"沖縄・奄美は温暖で、夏から秋にかけて台風の影響を受けやすいです。","id":"n350","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"standard","q":"長野県など中央高地で、昼夜の気温差が大きくなりやすい主な理由はどれですか？","choices":["内陸に位置するため","海に囲まれているため","赤道に近いため","雪がないため"],"answer":0,"a":"内陸では海の影響が小さいため、気温の日較差・年較差が大きくなりやすいです。","id":"n351","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"advanced","q":"日本の気候を多様にしている要因として適切なのはどれですか？","choices":["南北に長く山地も多いこと","国土が完全に平坦なこと","一年中同じ風が吹くこと","すべての地域が同じ標高であること"],"answer":0,"a":"日本は南北に長く、山地も多いため地域によって気候が異なります。","id":"n352","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"standard","q":"「からっ風」とよばれる乾いた風が吹くことで知られる地域はどれですか？","choices":["関東地方北部","北海道東部","沖縄県だけ","四国南部"],"answer":0,"a":"関東地方北部では冬に乾いた強風が吹くことがあり、からっ風と呼ばれます。","id":"n353","term":"2学期"},{"category":"geography","unit":"気候","difficulty":"standard","q":"冬に北海道東部などで流氷が見られる海はどれですか？","choices":["オホーツク海","瀬戸内海","東シナ海","有明海"],"answer":0,"a":"オホーツク海では冬に流氷が見られ、北海道の気候や漁業にも関係します。","id":"n354","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"basic","q":"土砂災害の一つで、斜面の土砂が大量に流れ下るものを何といいますか？","choices":["土石流","津波","高潮","液状化"],"answer":0,"a":"土石流は大量の土砂や石が水とともに流れ下る現象です。","id":"n355","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"basic","q":"急な斜面が崩れ落ちる災害を何といいますか？","choices":["がけ崩れ","高潮","洪水","津波"],"answer":0,"a":"がけ崩れは斜面が急に崩れる土砂災害です。","id":"n356","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"standard","q":"大雨によって山地の斜面がゆっくり滑り落ちる災害を何といいますか？","choices":["地すべり","津波","竜巻","液状化"],"answer":0,"a":"地すべりは斜面の土塊がゆっくり移動する現象です。","id":"n357","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"standard","q":"台風などで海面が異常に高くなり、海岸で浸水する災害を何といいますか？","choices":["高潮","津波","洪水","地すべり"],"answer":0,"a":"高潮は台風などによる気圧低下や強風で海面が上昇する現象です。","id":"n358","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"standard","q":"地震の発生直後に、まず身を守るために取る行動として適切なのはどれですか？","choices":["落下物から頭を守る","すぐにエレベーターへ乗る","窓際に立つ","火元を見に走る"],"answer":0,"a":"地震時はまず頭を守り、身の安全を確保します。","id":"n359","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"advanced","q":"津波から避難するときの行動として適切なのはどれですか？","choices":["海岸から離れ高台などへ避難する","津波を見に海岸へ行く","港へ戻る","低地で待つ"],"answer":0,"a":"津波警報などが出た場合は海岸から離れ、高台など安全な場所へ避難します。","id":"n360","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"standard","q":"災害時に家族と連絡が取れない場合に備えて、あらかじめ決めておくとよいものはどれですか？","choices":["集合場所や連絡方法","テレビ番組だけ","観光地の順番","買い物の予算"],"answer":0,"a":"家族の集合場所や連絡方法を事前に決めておくと役立ちます。","id":"n361","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"advanced","q":"「自助」とは防災において何を指しますか？","choices":["自分や家族の身を自分たちで守ること","行政だけが対応すること","地域の祭りを行うこと","海外から支援を受けること"],"answer":0,"a":"自助は自分自身や家族の命・生活を守るために自分たちで備えることです。","id":"n362","term":"2学期"},{"category":"geography","unit":"自然災害","difficulty":"advanced","q":"「共助」にあたる活動はどれですか？","choices":["地域住民が助け合うこと","政府だけが救助すること","一人で備蓄すること","海外へ旅行すること"],"answer":0,"a":"共助は地域や周囲の人々が互いに助け合うことです。","id":"n363","term":"2学期"},{"category":"geography","unit":"地域調査","difficulty":"basic","q":"地域調査で、実際に現地を訪れて調べる方法を何といいますか？","choices":["現地調査","文献調査","統計調査","聞き取り調査だけ"],"answer":0,"a":"現地調査は実際に地域を歩き、土地利用や施設などを観察する方法です。","id":"n364","term":"1学期"},{"category":"geography","unit":"地域調査","difficulty":"standard","q":"地域の人に質問して情報を集める調査方法はどれですか？","choices":["聞き取り調査","航空写真調査","等高線調査","気圧調査"],"answer":0,"a":"聞き取り調査では地域の人などに質問して情報を集めます。","id":"n365","term":"1学期"},{"category":"geography","unit":"地域調査","difficulty":"standard","q":"地形図の「凡例」は何を示しますか？","choices":["地図記号などの意味","標高だけ","人口だけ","気温だけ"],"answer":0,"a":"凡例は地図記号など、地図に使われている記号の意味を示します。","id":"n366","term":"1学期"},{"category":"geography","unit":"地域調査","difficulty":"advanced","q":"地域の特徴を地図上に色分けして示す方法の利点はどれですか？","choices":["分布や地域差を視覚的に比較しやすい","文章が不要になる","正確な数字が必ず分かる","調査が不要になる"],"answer":0,"a":"地図化すると分布や地域差を視覚的に把握しやすくなります。","id":"n367","term":"1学期"},{"category":"geography","unit":"地域調査","difficulty":"standard","q":"統計資料をグラフにするとき、割合の比較に向いているものはどれですか？","choices":["円グラフ","折れ線グラフだけ","地形図","写真"],"answer":0,"a":"円グラフは全体に占める割合の比較に向いています。","id":"n368","term":"1学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸幕府の将軍のうち、初代は誰ですか？","choices":["徳川家康","徳川家光","徳川吉宗","徳川慶喜"],"answer":0,"a":"初代将軍は徳川家康です。","id":"n369","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸幕府が藩を置く大名を、親藩・譜代・外様に分けたことを何と関連づけて考えますか？","choices":["大名統制","農地改革","選挙制度","身分解放"],"answer":0,"a":"大名の配置や区分は幕府による大名統制と関係しています。","id":"n370","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"幕府と藩が全国の土地と人民を支配する体制を何といいますか？","choices":["幕藩体制","院政","摂関政治","郡県制"],"answer":0,"a":"江戸時代の幕府と藩による支配体制を幕藩体制といいます。","id":"n371","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"大名が江戸に滞在することで幕府に多くの費用を負担させた制度はどれですか？","choices":["参勤交代","五人組","株仲間","寺子屋"],"answer":0,"a":"参勤交代は大名の負担を大きくすることで統制にも役立ちました。","id":"n372","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代、農村で連帯責任を負わせるために組織された制度はどれですか？","choices":["五人組","株仲間","座","藩校"],"answer":0,"a":"五人組は年貢納入や治安などについて連帯責任を負わせる制度です。","id":"n373","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に農民から年貢を納めさせる単位として整えられた村を何と関連づけますか？","choices":["村請制","株仲間","寺子屋","廃藩置県"],"answer":0,"a":"村全体で年貢を納める村請制が行われました。","id":"n374","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代の農民の税として中心だったものは何ですか？","choices":["年貢","関税","所得税","消費税"],"answer":0,"a":"農民は主に米などの形で年貢を納めました。","id":"n375","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に商人や職人が住む町を何と呼びましたか？","choices":["町","荘園","国衙","屯倉"],"answer":0,"a":"商人や職人が住む町は都市の重要な構成要素でした。","id":"n376","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代の交通で、江戸と各地を結んだ主要街道の一つはどれですか？","choices":["東海道","シルクロード","ベルリン道路","アメリカ街道"],"answer":0,"a":"東海道は江戸と京都・大坂を結ぶ主要街道です。","id":"n377","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"東海道五十三次を描いた浮世絵で知られる人物は誰ですか？","choices":["歌川広重","葛飾北斎","喜多川歌麿","俵屋宗達"],"answer":0,"a":"歌川広重は「東海道五十三次」などで知られます。","id":"n378","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"「富嶽三十六景」を描いた人物は誰ですか？","choices":["葛飾北斎","歌川広重","井原西鶴","松尾芭蕉"],"answer":0,"a":"葛飾北斎は「富嶽三十六景」で知られます。","id":"n379","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"俳諧を芸術として大成させた人物は誰ですか？","choices":["松尾芭蕉","近松門左衛門","十返舎一九","本居宣長"],"answer":0,"a":"松尾芭蕉は俳諧を大成した人物です。","id":"n380","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"人形浄瑠璃や歌舞伎などが栄えた江戸時代の文化を何といいますか？","choices":["町人文化","公家文化","武家文化だけ","天平文化"],"answer":0,"a":"都市の町人を担い手として町人文化が発展しました。","id":"n381","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"蘭学とは何を指しますか？","choices":["オランダ語を通して学んだ西洋の学問","中国の儒学だけ","日本古典だけ","仏教の宗派"],"answer":0,"a":"蘭学はオランダ語の書物などから西洋の医学・科学などを学ぶ学問です。","id":"n382","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"「解体新書」の翻訳で知られる人物は誰ですか？","choices":["杉田玄白","伊能忠敬","本居宣長","新井白石"],"answer":0,"a":"杉田玄白らが「解体新書」を翻訳しました。","id":"n383","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"全国を測量して日本地図を作った人物は誰ですか？","choices":["伊能忠敬","杉田玄白","吉田松陰","西郷隆盛"],"answer":0,"a":"伊能忠敬は全国を測量し、精密な日本地図の作成に取り組みました。","id":"n384","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"国学を大成し「古事記伝」を著した人物は誰ですか？","choices":["本居宣長","松尾芭蕉","福沢諭吉","坂本龍馬"],"answer":0,"a":"本居宣長は国学を大成し、「古事記伝」を著しました。","id":"n385","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸幕府が朱子学を重視した理由と関係が深い考えはどれですか？","choices":["身分秩序を重視する考え","自由貿易の推進","民主政治の実現","農地の国有化"],"answer":0,"a":"朱子学の身分秩序を重視する考えは幕府の支配と相性がよいものでした。","id":"n386","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"江戸時代の教育機関で、武士のために各藩が設けた学校を何といいますか？","choices":["藩校","寺子屋","大学校","私塾だけ"],"answer":0,"a":"各藩は武士の教育のために藩校を設けました。","id":"n387","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"庶民の子どもが「読み・書き・そろばん」などを学んだ場所は何ですか？","choices":["寺子屋","藩校","大学","兵学校"],"answer":0,"a":"寺子屋では庶民の子どもが読み書きや計算などを学びました。","id":"n388","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"江戸時代の三大都市に含まれる組み合わせはどれですか？","choices":["江戸・大阪・京都","江戸・奈良・福岡","大阪・札幌・横浜","京都・長崎・那覇"],"answer":0,"a":"江戸・大阪・京都は代表的な大都市でした。","id":"n389","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代、各地の特産品を売買する商人が多く集まった都市はどこですか？","choices":["大阪","佐渡","下田だけ","五島"],"answer":0,"a":"大阪は全国の商品流通の中心地の一つでした。","id":"n390","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"江戸時代に商人の同業組合として発達したものはどれですか？","choices":["株仲間","五人組","藩校","大政奉還"],"answer":0,"a":"株仲間は同業商人の組合です。","id":"n391","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"幕府が株仲間を公認する代わりに営業税を取る政策と関係が深い将軍は誰ですか？","choices":["徳川吉宗","徳川家康","徳川慶喜","明治天皇"],"answer":0,"a":"株仲間の公認・統制は江戸時代の商業政策の一部でした。","id":"n392","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"享保の改革で、裁判の基準などを示した法令集は何ですか？","choices":["公事方御定書","武家諸法度","五箇条の御誓文","御成敗式目"],"answer":0,"a":"公事方御定書は享保の改革で整えられました。","id":"n393","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"享保の改革で新田開発を奨励した目的として適切なのはどれですか？","choices":["幕府の収入を増やす","外国へ移住させる","工場を海外へ移す","選挙を実施する"],"answer":0,"a":"新田開発によって年貢収入の増加を図りました。","id":"n394","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"寛政の改革を行った老中は誰ですか？","choices":["松平定信","水野忠邦","田沼意次","井伊直弼"],"answer":0,"a":"松平定信が寛政の改革を行いました。","id":"n395","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"寛政の改革で、江戸に住む農民を農村に帰そうとした政策はどれですか？","choices":["旧里帰農令","人返しの法","上知令","大政奉還"],"answer":0,"a":"旧里帰農令は農村の立て直しをねらった政策です。","id":"n396","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"天保の改革で、水野忠邦が解散を命じた商人組織はどれですか？","choices":["株仲間","五人組","藩校","寺子屋"],"answer":0,"a":"水野忠邦は株仲間の解散を命じました。","id":"n397","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"天保の改革で、都市周辺の土地を幕府のものにしようとした政策はどれですか？","choices":["上知令","廃藩置県","五箇条の御誓文","人返しの法"],"answer":0,"a":"上知令は江戸・大阪周辺の土地を幕府領にしようとした政策です。","id":"n398","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"田沼意次が商人の力を利用して進めた政策と関係が深いのはどれですか？","choices":["商業を重視する政策","鎖国の完全強化","農地の公有化","身分制の廃止"],"answer":0,"a":"田沼意次は商業を重視し、株仲間を奨励するなどして幕府財政の立て直しを図りました。","id":"n399","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"田沼意次の政治で、商人から税を取るために利用された組織はどれですか？","choices":["株仲間","五人組","寺子屋","藩校"],"answer":0,"a":"株仲間から運上・冥加などを徴収しました。","id":"n400","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"1787年ごろに天明の飢饉の後で始まった改革はどれですか？","choices":["寛政の改革","享保の改革","天保の改革","明治維新"],"answer":0,"a":"寛政の改革は1787年に松平定信によって始められました。","id":"n401","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"江戸時代後半、ロシアなど外国船への警戒が強まる中で外国船を追い払う方針を示した法令はどれですか？","choices":["異国船打払令","薪水給与令","五箇条の御誓文","廃藩置県"],"answer":0,"a":"異国船打払令は1825年に出されました。","id":"n402","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"異国船打払令を改め、外国船へ燃料や水を与えて穏便に帰す方針を示した法令はどれですか？","choices":["薪水給与令","異国船打払令","上知令","武家諸法度"],"answer":0,"a":"薪水給与令は1842年に出され、異国船に燃料や水を与える方針を示しました。","id":"n403","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"フェートン号事件で問題となった外国船が入港した場所はどこですか？","choices":["長崎","江戸","大阪","下田"],"answer":0,"a":"1808年、フェートン号事件は長崎で起こりました。","id":"n404","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"basic","q":"シーボルトが日本で医学を教えた場所として知られるのはどこですか？","choices":["鳴滝塾","松下村塾","適塾","藩校明倫館"],"answer":0,"a":"シーボルトは長崎の鳴滝塾で医学などを教えました。","id":"n405","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"緒方洪庵が大阪で開いた蘭学の私塾は何ですか？","choices":["適塾","鳴滝塾","松下村塾","弘道館"],"answer":0,"a":"緒方洪庵は大阪で適塾を開きました。","id":"n406","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"江戸時代の社会で、農民や町人などを支配する側の身分として位置づけられたのはどれですか？","choices":["武士","百姓","町人","えた・ひにん"],"answer":0,"a":"江戸時代は武士を支配身分とする身分制度が整えられていました。","id":"n407","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"standard","q":"百姓・町人の中にも経済力を持つ人々が現れたことと関係が深いのはどれですか？","choices":["商品経済の発達","鎖国の完全化","貨幣の消滅","農業の消滅"],"answer":0,"a":"商品経済の発達によって一部の百姓・町人が富を蓄えました。","id":"n408","term":"2学期"},{"category":"history","unit":"江戸時代","difficulty":"advanced","q":"江戸時代に貨幣経済が発達したことを示すものはどれですか？","choices":["各地の特産品の売買の活発化","物々交換だけの社会","市場の消滅","街道の廃止"],"answer":0,"a":"市場や街道の発達とともに貨幣を使った商品売買が活発になりました。","id":"n409","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"basic","q":"1853年に浦賀へ来航したアメリカの使節は誰ですか？","choices":["ペリー","ハリス","マッカーサー","シーボルト"],"answer":0,"a":"ペリーは1853年に浦賀へ来航しました。","id":"n410","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"ペリー来航後、日本がアメリカと結んだ最初の条約は何ですか？","choices":["日米和親条約","日米修好通商条約","日英同盟","下関条約"],"answer":0,"a":"1854年に日米和親条約を結びました。","id":"n411","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"日米和親条約で開かれた港はどれですか？","choices":["下田・函館","横浜・神戸","長崎・大阪","鹿児島・那覇"],"answer":0,"a":"日米和親条約で下田と函館を開港しました。","id":"n412","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"1858年に結ばれた不平等条約は何ですか？","choices":["日米修好通商条約","日米和親条約","五箇条の御誓文","ポーツマス条約"],"answer":0,"a":"日米修好通商条約は1858年に結ばれました。","id":"n413","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"advanced","q":"日米修好通商条約で日本が認めることになった、外国人を自国の法律で裁く制度を何といいますか？","choices":["領事裁判権","関税自主権","参勤交代","版籍奉還"],"answer":0,"a":"領事裁判権は外国人を日本の裁判で裁けない仕組みで、日本に不利な内容でした。","id":"n414","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"advanced","q":"日米修好通商条約などで、日本が失ったとされる権利はどれですか？","choices":["関税自主権","参政権","教育権","選挙権"],"answer":0,"a":"不平等条約では関税自主権が制限されました。","id":"n415","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"江戸幕府が外国船への対応をめぐって出した政策として、朝廷の許可を得ようとしたことと関係が深いのはどれですか？","choices":["公武合体","廃藩置県","文明開化","富国強兵"],"answer":0,"a":"幕末には朝廷と幕府の関係を強める公武合体論も唱えられました。","id":"n416","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"basic","q":"薩摩藩と長州藩が同盟を結ぶ仲介をした人物は誰ですか？","choices":["坂本龍馬","西郷隆盛","吉田松陰","大久保利通"],"answer":0,"a":"坂本龍馬らの働きで薩長同盟が成立しました。","id":"n417","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"薩長同盟は何年に結ばれましたか？","choices":["1866年","1853年","1871年","1889年"],"answer":0,"a":"薩長同盟は1866年に結ばれました。","id":"n418","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"徳川慶喜が政権を朝廷へ返上した出来事を何といいますか？","choices":["大政奉還","版籍奉還","廃藩置県","王政復古"],"answer":0,"a":"1867年、徳川慶喜は大政奉還を行いました。","id":"n419","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"basic","q":"1868年、天皇を中心とする新政府をつくることを示した出来事はどれですか？","choices":["王政復古の大号令","参勤交代","異国船打払令","五箇条の御誓文"],"answer":0,"a":"王政復古の大号令で新政府の成立へ向かいました。","id":"n420","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"advanced","q":"戊辰戦争の中で新政府軍と旧幕府軍が戦った有名な戦いはどれですか？","choices":["鳥羽・伏見の戦い","関ヶ原の戦い","壇ノ浦の戦い","長篠の戦い"],"answer":0,"a":"戊辰戦争の初戦の一つが鳥羽・伏見の戦いです。","id":"n421","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"江戸が新政府に明け渡された際の交渉で知られる人物はどれですか？","choices":["勝海舟","近藤勇","大塩平八郎","田沼意次"],"answer":0,"a":"勝海舟は西郷隆盛と交渉し、江戸城の無血開城に尽力しました。","id":"n422","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"advanced","q":"江戸城の無血開城は何年に行われましたか？","choices":["1868年","1854年","1877年","1889年"],"answer":0,"a":"江戸城の無血開城は1868年に行われました。","id":"n423","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"standard","q":"新政府に反対して北海道に渡り、五稜郭で戦った旧幕府軍の人物は誰ですか？","choices":["榎本武揚","坂本龍馬","木戸孝允","板垣退助"],"answer":0,"a":"榎本武揚は蝦夷地へ渡り、五稜郭を拠点に戦いました。","id":"n424","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"advanced","q":"幕末の「尊王攘夷」の「尊王」とは何を重んじることですか？","choices":["天皇を尊ぶこと","将軍を廃止すること","外国を受け入れること","商人を保護すること"],"answer":0,"a":"尊王は天皇を尊ぶという意味です。","id":"n425","term":"2学期"},{"category":"history","unit":"幕末","difficulty":"advanced","q":"幕末の「尊王攘夷」の「攘夷」とは何を意味しますか？","choices":["外国勢力を退けること","貿易を自由化すること","農民を解放すること","選挙を行うこと"],"answer":0,"a":"攘夷は外国勢力を退けようとする考えです。","id":"n426","term":"2学期"},{"category":"history","unit":"明治維新","difficulty":"basic","q":"明治政府が1869年に行った、大名が土地と人民を朝廷に返上した出来事は何ですか？","choices":["版籍奉還","廃藩置県","大政奉還","五箇条の御誓文"],"answer":0,"a":"版籍奉還は1869年に行われました。","id":"n427","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"basic","q":"1871年に藩を廃止して府県を置いた政策は何ですか？","choices":["廃藩置県","版籍奉還","地租改正","徴兵令"],"answer":0,"a":"1871年に廃藩置県が行われ、全国を府県に再編しました。","id":"n428","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"明治政府が近代国家づくりの基本方針として示したものはどれですか？","choices":["五箇条の御誓文","武家諸法度","公事方御定書","異国船打払令"],"answer":0,"a":"五箇条の御誓文は1868年に新政府の基本方針として示されました。","id":"n429","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"明治政府が国民から兵士を集めるために1873年に出した法令は何ですか？","choices":["徴兵令","学制","地租改正条例","廃藩置県令"],"answer":0,"a":"1873年に徴兵令が出されました。","id":"n430","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"basic","q":"1872年に定められた近代的な学校制度は何ですか？","choices":["学制","徴兵令","地租改正","民法"],"answer":0,"a":"1872年に学制が公布されました。","id":"n431","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"明治政府が土地の所有者に地券を発行し、土地価格を基準に税を現金で納めさせた改革は何ですか？","choices":["地租改正","版籍奉還","徴兵令","殖産興業"],"answer":0,"a":"地租改正では地券に示された地価を基準に地租を現金で納めました。","id":"n432","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"地租改正によって、政府が安定した税収を得やすくなったのはなぜですか？","choices":["地価を基準に現金で税を納めたから","米だけで納めたから","税がなくなったから","藩が税を集めたから"],"answer":0,"a":"地租改正は地価を基準に現金で納める仕組みで、政府の安定した財源となりました。","id":"n433","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"明治政府が工場や鉱山を経営して近代産業を育てた政策を何といいますか？","choices":["殖産興業","文明開化","富国強兵","尊王攘夷"],"answer":0,"a":"殖産興業は産業を育成する政策です。","id":"n434","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"basic","q":"「文明開化」とは何を指しますか？","choices":["西洋の文化や制度を取り入れた社会の変化","江戸時代の文化復興","鎖国の強化","農民の武士化"],"answer":0,"a":"文明開化は西洋の文化・制度・技術などを取り入れる動きです。","id":"n435","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"明治時代に鉄道が最初に開通した区間はどれですか？","choices":["新橋―横浜","東京―大阪","京都―神戸","新宿―上野"],"answer":0,"a":"1872年に新橋―横浜間が開通しました。","id":"n436","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"福沢諭吉が著した、学問の重要性を説いた本はどれですか？","choices":["学問のすゝめ","古事記伝","文明論之概略だけ","日本外史"],"answer":0,"a":"福沢諭吉の「学問のすゝめ」は学問の重要性を説きました。","id":"n437","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"明治初期に政府が掲げた「富国強兵」は何を目指した政策ですか？","choices":["国を豊かにし軍事力を強めること","農業だけに集中すること","外国との貿易を禁止すること","藩を復活させること"],"answer":0,"a":"富国強兵は経済を発展させ軍事力を強化することを目指しました。","id":"n438","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"自由民権運動で人々が求めたものとして代表的なのはどれですか？","choices":["国会の開設や政治参加","参勤交代の復活","鎖国の強化","身分制度の復活"],"answer":0,"a":"自由民権運動では国会開設や政治参加の拡大などが求められました。","id":"n439","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"自由民権運動を進めた代表的人物は誰ですか？","choices":["板垣退助","徳川家康","水野忠邦","伊能忠敬"],"answer":0,"a":"板垣退助は自由民権運動の中心人物の一人です。","id":"n440","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"板垣退助らが結成した政党は何ですか？","choices":["自由党","立憲改進党","政友会","立憲政友会"],"answer":0,"a":"1881年、板垣退助らは自由党を結成しました。","id":"n441","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"大隈重信と関係が深い政党はどれですか？","choices":["立憲改進党","自由党","自由民権党","憲政党だけ"],"answer":0,"a":"大隈重信らは立憲改進党を結成しました。","id":"n442","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"basic","q":"1889年に発布された日本の近代憲法は何ですか？","choices":["大日本帝国憲法","日本国憲法","五箇条の御誓文","民法"],"answer":0,"a":"大日本帝国憲法は1889年に発布されました。","id":"n443","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"大日本帝国憲法のもとで、主権を持つとされたのは誰ですか？","choices":["天皇","国民","内閣総理大臣","衆議院"],"answer":0,"a":"大日本帝国憲法では天皇主権とされました。","id":"n444","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"1889年の大日本帝国憲法発布当時、内閣総理大臣を務めていた人物は誰ですか？","choices":["黒田清隆","伊藤博文","板垣退助","福沢諭吉"],"answer":0,"a":"大日本帝国憲法の発布時の首相は黒田清隆です。","id":"n445","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"初代内閣総理大臣は誰ですか？","choices":["伊藤博文","黒田清隆","山県有朋","西郷隆盛"],"answer":0,"a":"初代内閣総理大臣は伊藤博文です。","id":"n446","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"1890年に開設された近代日本の議会は何ですか？","choices":["帝国議会","国会議事堂","枢密院","太政官"],"answer":0,"a":"1890年に帝国議会が開設されました。","id":"n447","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"帝国議会を構成した二つの院はどれですか？","choices":["貴族院と衆議院","参議院と衆議院","元老院と貴族院","参議院と貴族院"],"answer":0,"a":"帝国議会は貴族院と衆議院から構成されました。","id":"n448","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"明治政府が国民統合のために行った政策として「四民平等」は何を意味しますか？","choices":["士農工商の身分を廃止する方向へ進めた","武士だけを優遇する","農民を武士にする","外国人だけに参政権を与える"],"answer":0,"a":"明治政府は旧身分制度を改め、四民平等を掲げました。","id":"n449","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"旧武士のうち、明治政府の政策に不満を持った人々が起こした反乱を総称して何といいますか？","choices":["士族反乱","農民一揆","百姓一揆","打ちこわし"],"answer":0,"a":"明治初期には士族反乱が相次ぎました。","id":"n450","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"basic","q":"1877年に起きた最大の士族反乱は何ですか？","choices":["西南戦争","戊辰戦争","佐賀の乱","萩の乱"],"answer":0,"a":"1877年に西南戦争が起こりました。","id":"n451","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"西南戦争を率いた人物は誰ですか？","choices":["西郷隆盛","大久保利通","木戸孝允","伊藤博文"],"answer":0,"a":"西郷隆盛が西南戦争を指導しました。","id":"n452","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"「征韓論」をめぐって政府内で対立し、下野した人物として知られるのは誰ですか？","choices":["西郷隆盛","大隈重信","福沢諭吉","黒田清隆"],"answer":0,"a":"西郷隆盛らは征韓論をめぐって政府を去りました。","id":"n453","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"明治政府が北海道の開拓を進めるために設置した役所は何ですか？","choices":["開拓使","鎮台","枢密院","民部省"],"answer":0,"a":"開拓使は北海道の開拓を担当しました。","id":"n454","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"北海道の開拓にあたって政府が設けた開拓民などの組織は何ですか？","choices":["屯田兵","五人組","株仲間","志士"],"answer":0,"a":"屯田兵は開拓と防衛の役割を担いました。","id":"n455","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"明治政府が中央集権国家を目指した理由として適切なのはどれですか？","choices":["全国を統一的に統治し近代国家をつくるため","藩を強化するため","幕府を復活させるため","外国に日本を分割してもらうため"],"answer":0,"a":"廃藩置県などは中央集権化を進める政策でした。","id":"n456","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"standard","q":"明治時代、国民に納税や兵役などの制度を広く適用したことと関係が深いのはどれですか？","choices":["近代国家の国民制度の形成","鎌倉幕府の成立","荘園制の発展","参勤交代の復活"],"answer":0,"a":"近代国家として全国民を制度的に組み込む政策が進みました。","id":"n457","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"条約改正で、領事裁判権の撤廃に成功した外務大臣は誰ですか？","choices":["陸奥宗光","小村寿太郎","伊藤博文","大隈重信"],"answer":0,"a":"陸奥宗光は1894年に領事裁判権の撤廃に成功しました。","id":"n458","term":"3学期"},{"category":"history","unit":"明治維新","difficulty":"advanced","q":"関税自主権の完全回復を実現した人物は誰ですか？","choices":["小村寿太郎","陸奥宗光","板垣退助","西園寺公望"],"answer":0,"a":"小村寿太郎の交渉により1911年に関税自主権が完全回復しました。","id":"n459","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法が施行された年はいつですか？","choices":["1947年","1945年","1950年","1931年"],"answer":0,"a":"日本国憲法は1947年5月3日に施行されました。","id":"n460","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法の基本原理の一つで、政治の最終的な決定権が国民にある考えを何といいますか？","choices":["国民主権","基本的人権の尊重","平和主義","地方自治"],"answer":0,"a":"国民主権は政治の最終的な決定権が国民にあるという考えです。","id":"n461","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"basic","q":"日本国憲法の基本原理の一つで、日本が戦争を放棄することを示すものはどれですか？","choices":["平和主義","国民主権","基本的人権の尊重","法の支配"],"answer":0,"a":"日本国憲法は平和主義を基本原理の一つとしています。","id":"n462","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"standard","q":"日本国憲法で定められる「象徴」とされているのは誰ですか？","choices":["天皇","内閣総理大臣","国会議員","最高裁判所長官"],"answer":0,"a":"日本国憲法第1条で、天皇は日本国および日本国民統合の象徴とされています。","id":"n463","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"standard","q":"日本国憲法第9条で、国際紛争を解決する手段として放棄すると定められているものはどれですか？","choices":["戦争","外交","貿易","裁判"],"answer":0,"a":"第9条は戦争の放棄などを定めています。","id":"n464","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"advanced","q":"日本国憲法の改正を発議することができるのはどれですか？","choices":["国会","内閣","最高裁判所","地方議会だけ"],"answer":0,"a":"憲法改正の発議は国会が行います。","id":"n465","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"advanced","q":"憲法改正案の国民投票で、承認に必要なのは何ですか？","choices":["国民投票での過半数の賛成","国会議員全員の賛成だけ","内閣の決定だけ","最高裁の判決だけ"],"answer":0,"a":"国民投票で過半数の賛成を得ることが必要です。","id":"n466","term":"3学期"},{"category":"civics","unit":"日本国憲法","difficulty":"standard","q":"国の最高法規である日本国憲法に反する法律を無効と判断できる制度を何といいますか？","choices":["違憲審査制","参政権","直接請求権","住民投票"],"answer":0,"a":"違憲審査制により裁判所は法律などが憲法に適合するか判断できます。","id":"n467","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"basic","q":"日本国憲法が保障する、人が生まれながらに持つ権利を何といいますか？","choices":["基本的人権","参政権だけ","社会保障","納税義務"],"answer":0,"a":"基本的人権は憲法で保障される重要な権利です。","id":"n468","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"standard","q":"すべての人が法の下で平等に扱われることを保障する権利はどれですか？","choices":["平等権","請求権","社会権","参政権"],"answer":0,"a":"平等権は法の下の平等などを保障します。","id":"n469","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"basic","q":"自由にものを考えたり信じたりする自由を何といいますか？","choices":["思想・良心の自由","職業選択の自由","居住・移転の自由","通信の秘密"],"answer":0,"a":"思想・良心の自由は精神的自由の一つです。","id":"n470","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"standard","q":"自分の宗教を信じるか信じないかを自ら決める自由はどれですか？","choices":["信教の自由","表現の自由","学問の自由","職業選択の自由"],"answer":0,"a":"信教の自由は宗教を信じる・信じないことについての自由です。","id":"n471","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"basic","q":"自分の意見や情報を表現する自由を何といいますか？","choices":["表現の自由","財産権","請願権","労働基本権"],"answer":0,"a":"表現の自由は精神的自由の重要な一つです。","id":"n472","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"standard","q":"健康で文化的な最低限度の生活を営む権利は何ですか？","choices":["生存権","教育を受ける権利","勤労の権利","参政権"],"answer":0,"a":"生存権は社会権の一つです。","id":"n473","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"standard","q":"教育を受ける権利は何と関係が深いですか？","choices":["社会権","自由権だけ","参政権だけ","請求権だけ"],"answer":0,"a":"教育を受ける権利は社会権に含まれます。","id":"n474","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"standard","q":"労働者が団結して交渉や行動をする権利をまとめて何といいますか？","choices":["労働基本権","参政権","請求権","新しい人権"],"answer":0,"a":"団結権・団体交渉権・団体行動権を労働基本権といいます。","id":"n475","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"advanced","q":"環境権やプライバシーの権利などをまとめて何と呼ぶことがありますか？","choices":["新しい人権","参政権","社会権だけ","納税権"],"answer":0,"a":"新しい人権として環境権やプライバシーの権利などが論じられています。","id":"n476","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"standard","q":"裁判を受ける権利など、国に対して救済を求める権利を何といいますか？","choices":["請求権","平等権","社会権","参政権"],"answer":0,"a":"請求権は裁判を受ける権利など、国に対して一定の行為を求める権利です。","id":"n477","term":"3学期"},{"category":"civics","unit":"基本的人権","difficulty":"advanced","q":"人権と人権が衝突する場合に、他者の人権にも配慮して調整する考え方を何といいますか？","choices":["公共の福祉","三権分立","地方自治","国民主権"],"answer":0,"a":"公共の福祉との調整が人権制約の根拠として論じられます。","id":"n478","term":"3学期"},{"category":"civics","unit":"国会","difficulty":"basic","q":"国会は国権の最高機関であり、何の唯一の立法機関とされていますか？","choices":["国民","国家","裁判所","地方自治体"],"answer":0,"a":"日本国憲法では国会は国の唯一の立法機関とされています。","id":"n479","term":"3学期"},{"category":"civics","unit":"国会","difficulty":"standard","q":"衆議院議員の任期は原則何年ですか？","choices":["4年","6年","3年","5年"],"answer":0,"a":"衆議院議員の任期は4年ですが、解散があるため満了前に終了することがあります。","id":"n480","term":"3学期"},{"category":"civics","unit":"国会","difficulty":"advanced","q":"衆議院が参議院より強い立場を持つことを示す制度はどれですか？","choices":["衆議院の優越","政教分離","司法取引","地方交付税"],"answer":0,"a":"予算や条約、内閣総理大臣の指名などで衆議院の優越が認められています。","id":"n481","term":"3学期"},{"category":"civics","unit":"国会","difficulty":"standard","q":"法律案が国会で成立するまでに、原則として必要なのはどれですか？","choices":["両議院で可決すること","内閣だけの決定","最高裁だけの決定","天皇だけの決定"],"answer":0,"a":"原則として衆議院・参議院の両方で可決される必要があります。","id":"n482","term":"3学期"},{"category":"civics","unit":"国会","difficulty":"advanced","q":"国会が政府の仕事を調べるために行う権限は何といいますか？","choices":["国政調査権","違憲審査権","外交権","監督権"],"answer":0,"a":"国会は国政調査権を持ちます。","id":"n483","term":"3学期"},{"category":"civics","unit":"内閣","difficulty":"basic","q":"行政を担当する機関はどれですか？","choices":["内閣","国会","裁判所","地方議会"],"answer":0,"a":"行政権は内閣に属します。","id":"n484","term":"3学期"},{"category":"civics","unit":"内閣","difficulty":"standard","q":"内閣の長である内閣総理大臣を指名するのはどこですか？","choices":["国会","最高裁判所","天皇","地方議会"],"answer":0,"a":"内閣総理大臣は国会の議決で指名されます。","id":"n485","term":"3学期"},{"category":"civics","unit":"内閣","difficulty":"basic","q":"内閣は何と呼ばれる大臣から構成されますか？","choices":["国務大臣","都道府県知事","裁判官","国会議員だけ"],"answer":0,"a":"内閣は内閣総理大臣と国務大臣で組織されます。","id":"n486","term":"3学期"},{"category":"civics","unit":"内閣","difficulty":"advanced","q":"内閣が国会に対して責任を負うしくみを何といいますか？","choices":["議院内閣制","大統領制","封建制","身分制"],"answer":0,"a":"日本は議院内閣制で、内閣は国会に対して連帯して責任を負います。","id":"n487","term":"3学期"},{"category":"civics","unit":"内閣","difficulty":"standard","q":"衆議院で内閣不信任決議が可決された場合、内閣はどうするかを選ぶことになりますか？","choices":["10日以内の衆議院解散か総辞職","参議院解散だけ","最高裁解散","天皇の退位"],"answer":0,"a":"内閣は10日以内に衆議院を解散しない限り総辞職しなければなりません。","id":"n488","term":"3学期"},{"category":"civics","unit":"裁判所","difficulty":"basic","q":"日本の裁判所の頂点にある裁判所はどこですか？","choices":["最高裁判所","東京高等裁判所","大阪地方裁判所","家庭裁判所"],"answer":0,"a":"最高裁判所が司法の頂点です。","id":"n489","term":"3学期"},{"category":"civics","unit":"裁判所","difficulty":"standard","q":"第一審を担当することが多い裁判所はどれですか？","choices":["地方裁判所","最高裁判所だけ","簡易裁判所だけ","家庭裁判所だけ"],"answer":0,"a":"民事・刑事事件の多くは地方裁判所などが第一審を担当します。","id":"n490","term":"3学期"},{"category":"civics","unit":"裁判所","difficulty":"standard","q":"少年事件などを扱う裁判所はどこですか？","choices":["家庭裁判所","最高裁判所","高等裁判所だけ","地方議会"],"answer":0,"a":"家庭裁判所は少年事件や家庭に関する事件などを扱います。","id":"n491","term":"3学期"},{"category":"civics","unit":"裁判所","difficulty":"advanced","q":"裁判官が自分の良心に従い、憲法と法律にのみ拘束されることは何を保障するものですか？","choices":["司法権の独立","地方自治","国民主権","議院内閣制"],"answer":0,"a":"裁判官の独立は公正な裁判を行うために重要です。","id":"n492","term":"3学期"},{"category":"civics","unit":"裁判所","difficulty":"standard","q":"最高裁判所の裁判官について、国民がその適否を判断する制度は何ですか？","choices":["国民審査","国民投票","住民監査請求","解散総選挙"],"answer":0,"a":"最高裁判所裁判官の国民審査は衆議院議員総選挙と同時に行われます。","id":"n493","term":"3学期"},{"category":"civics","unit":"三権分立","difficulty":"basic","q":"立法・行政・司法の権力を分けて相互に抑制する考えを何といいますか？","choices":["三権分立","地方自治","議院内閣制","基本的人権"],"answer":0,"a":"三権分立は権力の集中を防ぐしくみです。","id":"n494","term":"3学期"},{"category":"civics","unit":"三権分立","difficulty":"advanced","q":"法律が憲法に違反していないかを裁判所が審査する権限は何ですか？","choices":["違憲審査権","国政調査権","予算議決権","条約承認権"],"answer":0,"a":"違憲審査権は司法権による立法・行政へのチェックの一つです。","id":"n495","term":"3学期"},{"category":"civics","unit":"三権分立","difficulty":"advanced","q":"国会が内閣をコントロールする例として適切なのはどれですか？","choices":["予算を議決する","裁判官を全員解任する","地方議会を直接運営する","憲法を単独で改正する"],"answer":0,"a":"国会は予算の議決や法律の制定などを通じて内閣をチェックします。","id":"n496","term":"3学期"},{"category":"civics","unit":"地方自治","difficulty":"basic","q":"地域の住民が自分たちの地域の政治を行う考えを何といいますか？","choices":["地方自治","国民主権","三権分立","中央集権"],"answer":0,"a":"地方自治は地方のことを地域住民が自ら治めるという考えです。","id":"n497","term":"3学期"},{"category":"civics","unit":"地方自治","difficulty":"basic","q":"都道府県や市区町村の長を何といいますか？","choices":["首長","議長","裁判官","国務大臣"],"answer":0,"a":"都道府県知事や市区町村長を首長と呼びます。","id":"n498","term":"3学期"},{"category":"civics","unit":"地方自治","difficulty":"standard","q":"地方議会の議員や首長を住民が直接選ぶことを何といいますか？","choices":["直接選挙","間接選挙","制限選挙","比例代表だけ"],"answer":0,"a":"地方政治では住民が首長と議会議員を直接選びます。","id":"n499","term":"3学期"},{"category":"civics","unit":"地方自治","difficulty":"advanced","q":"住民が条例の制定や改廃を求めることができる制度はどれですか？","choices":["直接請求権","国政調査権","違憲審査権","拒否権"],"answer":0,"a":"地方自治では条例制定・改廃請求などの直接請求権が認められています。","id":"n500","term":"3学期"}];


const STORAGE="shakaiState_v07";
const DEFAULT_SCOPES={mid:["日本の地域構成","人口","産業","江戸時代"],final:["気候","自然災害","江戸時代","幕末","明治維新"]};
const defaultState={stats:{},answers:0,correct:0,flash:{},tests:[],scopes:JSON.parse(JSON.stringify(DEFAULT_SCOPES)),sessions:[],term:"all"};
let state=loadState(),screen="home",test=null,flash=null,timerId=null;
function loadState(){try{const fresh=JSON.parse(localStorage.getItem(STORAGE)||"null");if(fresh)return normalize(fresh);const old=JSON.parse(localStorage.getItem("shakaiState_v06")||localStorage.getItem("shakaiState_v05")||localStorage.getItem("shakaiState_v04")||"null");return old?normalize(old):structuredClone(defaultState)}catch(e){return structuredClone(defaultState)}}
function normalize(x){const s=structuredClone(defaultState);Object.assign(s,x);s.stats=x.stats||{};s.flash=x.flash||{};s.tests=x.tests||[];s.sessions=x.sessions||[];s.scopes={mid:x.scopes?.mid?.length?x.scopes.mid:DEFAULT_SCOPES.mid.slice(),final:x.scopes?.final?.length?x.scopes.final:DEFAULT_SCOPES.final.slice()};s.term=["all","1学期","2学期","3学期"].includes(x.term)?x.term:"all";return s}
function saveState(){localStorage.setItem(STORAGE,JSON.stringify(state))}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function catName(c){return {geography:"地理",history:"歴史",civics:"公民"}[c]||c}function diffName(d){return {basic:"基礎",standard:"標準",advanced:"応用"}[d]||d}
function termName(t){return t==="all"?"すべて":t}
function termFilter(q){return state.term==="all"||q.term===state.term}
function setTerm(t){state.term=t;saveState();render()}
function filteredQs(pool=QUESTIONS){return pool.filter(termFilter)}
function statFor(id){if(!state.stats[id])state.stats[id]={attempts:0,correct:0,wrong:0,streak:0,last:0};return state.stats[id]}
function weakness(q){const s=statFor(q.id),f=state.flash[q.id];let w=s.attempts===0?30:(1-s.correct/s.attempts)*70+(s.streak===0?15:0);if(f==="bad")w+=25;else if(f==="maybe")w+=12;return Math.min(100,Math.round(w))}
function weakQs(pool=null){const base=pool||QUESTIONS;return base.filter(q=>termFilter(q)&&weakness(q)>=45).sort((a,b)=>weakness(b)-weakness(a))}
function unitStats(){const m={};QUESTIONS.forEach(q=>{const s=statFor(q.id);m[q.unit]??={category:q.category,attempts:0,correct:0,weak:0};m[q.unit].attempts+=s.attempts;m[q.unit].correct+=s.correct;if(weakness(q)>=45)m[q.unit].weak++});return m}
function recentDate(){return new Date().toLocaleDateString("ja-JP",{month:"long",day:"numeric"})}
function render(){if(timerId&&screen!=="testRun"){clearInterval(timerId);timerId=null}const root=document.getElementById("app");root.innerHTML=nav()+`<div class="page">${({home:homeView,study:studyView,testSetup:testSetupView,testRun:testRunView,flash:flashView,stats:statsView,scope:scopeView,review:reviewView}[screen]||homeView)()}</div>`;if(screen==="testRun"){bindTestRun();startTimer()}if(screen==="flash")bindFlash()}
function nav(){return `<div class="nav">${[["home","🏠 ホーム"],["study","📖 学習"],["testSetup","📝 テスト"],["stats","📊 成績"],["scope","⚙️ 範囲"]].map(x=>`<button class="${screen===x[0]?"active":""}" onclick="go('${x[0]}')">${x[1]}</button>`).join("")}</div>`}
function go(s){screen=s;test=null;flash=null;render()}
function homeView(){const total=state.answers,acc=total?Math.round(state.correct/total*100):0,available=filteredQs(),weak=weakQs(available),units=unitStats(),top=Object.entries(units).filter(x=>available.some(q=>q.unit===x[0])&&x[1].weak).sort((a,b)=>b[1].weak-a[1].weak).slice(0,3);return `<div class="hero"><div class="term-select"><label class="field">学ぶ時期<select id="homeTerm" onchange="setTerm(this.value)"><option value="all" ${state.term==="all"?"selected":""}>すべて</option><option value="1学期" ${state.term==="1学期"?"selected":""}>1学期</option><option value="2学期" ${state.term==="2学期"?"selected":""}>2学期</option><option value="3学期" ${state.term==="3学期"?"selected":""}>3学期</option></select></label><p class="muted">現在：${termName(state.term)}　・　学校の進度に合わせて切り替えられます。</p></div><h2>今日の学習メニュー</h2><p>${recentDate()}のおすすめを、今の学習状況から自動で作ります。</p><div class="actions"><button class="btn" onclick="startDaily()">今日の5問を始める</button>${weak.length?`<button class="btn warn" onclick="startWeakStudy()">${termName(state.term)}の苦手を克服</button>`:`<button class="btn secondary" onclick="go('study')">まず学習する</button>`}</div></div><div class="card"><div class="section-title"><h2>学習状況</h2><span class="badge">全500問・${termName(state.term)}</span></div><div class="statgrid"><div class="stat"><span class="muted">正答率</span><b>${acc}%</b></div><div class="stat"><span class="muted">回答数</span><b>${total}</b></div><div class="stat"><span class="muted">今学期の苦手</span><b>${weak.length}</b></div><div class="stat"><span class="muted">テスト回数</span><b>${state.tests.length}</b></div></div></div><div class="grid2"><div class="card"><h3>おすすめ単元</h3>${top.length?top.map(([u,v])=>`<div class="unit-row"><span>${esc(u)}</span><b>${v.weak}問</b></div>`).join(""):`<p class="muted">まだ学習記録がありません。まず5問から始めましょう。</p>`}</div><div class="card"><h3>学期の使い方</h3><p class="muted">1学期・2学期・3学期を選ぶと、学習・今日の5問・苦手学習・テストの対象をその学期に絞れます。</p><p class="muted">※学校によって進度は異なるため、必要なら「すべて」に戻してください。</p></div></div>`}
function startDaily(){let pool=filteredQs();let qs=weakQs(pool).slice(0,5);if(qs.length<5){const used=new Set(qs.map(x=>x.id));qs=qs.concat(pool.filter(q=>!used.has(q.id)).sort(()=>Math.random()-.5).slice(0,5-qs.length))}beginCustomTest(qs,"daily")}
function beginCustomTest(qs,type){test={type,qs:qs.slice(),i:0,selected:null,score:0,started:Date.now(),limit:0,results:[]};screen="testRun";render()}
function studyView(){return `<div class="card"><h2>📖 フラッシュカード <span class="tag">全500問</span></h2><p class="muted">学ぶ時期を選んで、まず覚える。答えを見たあと「まだ・あやしい・覚えた」で自己評価できます。</p><label class="field">学ぶ時期<select id="studyTerm" onchange="setTerm(this.value)"><option value="all" ${state.term==="all"?"selected":""}>すべて</option><option value="1学期" ${state.term==="1学期"?"selected":""}>1学期</option><option value="2学期" ${state.term==="2学期"?"selected":""}>2学期</option><option value="3学期" ${state.term==="3学期"?"selected":""}>3学期</option></select></label><label class="field">分野<select id="studyCat" onchange="updateStudyUnits()"><option value="all">すべて</option><option value="geography">地理</option><option value="history">歴史</option><option value="civics">公民</option></select></label><label class="field">単元<select id="studyUnit"><option value="all">すべて</option>${[...new Set(filteredQs().map(q=>q.unit))].map(u=>`<option>${esc(u)}</option>`).join("")}</select></label><div class="actions"><button class="btn" onclick="startFlashFromStudy()">学習開始</button><button class="btn warn" onclick="startWeakStudy()">苦手だけ学ぶ</button></div></div>`}
function updateStudyUnits(){const cat=document.getElementById("studyCat").value,units=[...new Set(filteredQs().filter(q=>cat==="all"||q.category===cat).map(q=>q.unit))];document.getElementById("studyUnit").innerHTML='<option value="all">すべて</option>'+units.map(u=>`<option>${esc(u)}</option>`).join("")}
function startFlashFromStudy(){const cat=document.getElementById("studyCat").value,unit=document.getElementById("studyUnit").value;startFlash(filteredQs().filter(q=>(cat==="all"||q.category===cat)&&(unit==="all"||q.unit===unit)))}
function startWeakStudy(){const qs=weakQs(filteredQs()).slice(0,20);startFlash(qs.length?qs:filteredQs().slice().sort(()=>Math.random()-.5).slice(0,10))}
function startFlash(qs){flash={qs:[...qs],i:0,show:false};screen="flash";render()}
function flashView(){if(!flash)return `<div class="card"><h2>フラッシュカード</h2></div>`;const q=flash.qs[flash.i];if(!q)return `<div class="card empty"><h2>学習完了！</h2><p>今回のカードを確認しました。</p><button class="btn" onclick="go('home')">ホームへ</button></div>`;return `<div class="card"><div class="muted">${flash.i+1} / ${flash.qs.length}　<span class="tag">${catName(q.category)}</span><span class="tag">${esc(q.unit)}</span></div><div class="progress"><i style="width:${flash.i/flash.qs.length*100}%"></i></div><h2>${esc(q.q)}</h2>${flash.show?`<div class="notice"><b>答え</b><p>${esc(q.choices[q.answer])}</p><b>解説</b><p>${esc(q.a)}</p></div><div class="actions"><button class="btn bad" data-rate="bad">まだ覚えていない</button><button class="btn warn" data-rate="maybe">あやしい</button><button class="btn good" data-rate="good">覚えた</button></div>`:`<button class="btn full" id="showAnswer">答えを見る</button>`}</div>`}
function bindFlash(){document.getElementById("showAnswer")?.addEventListener("click",()=>{flash.show=true;render()});document.querySelectorAll("[data-rate]").forEach(b=>b.addEventListener("click",()=>{state.flash[flash.qs[flash.i].id]=b.dataset.rate;saveState();flash.i++;flash.show=false;render()}))}
function testSetupView(){return `<div class="card"><h2>📝 テスト設定 <span class="tag">500問から出題</span></h2><label class="field">学ぶ時期<select id="testTerm" onchange="setTerm(this.value)"><option value="all" ${state.term==="all"?"selected":""}>すべて</option><option value="1学期" ${state.term==="1学期"?"selected":""}>1学期</option><option value="2学期" ${state.term==="2学期"?"selected":""}>2学期</option><option value="3学期" ${state.term==="3学期"?"selected":""}>3学期</option></select></label><label class="field">テスト種類<select id="testType" onchange="applyPreset()"><option value="free">自由に選ぶ</option><option value="mid">中間テスト対策</option><option value="final">期末テスト対策</option><option value="weak">苦手テスト</option></select></label><label class="field">分野<select id="testCat" onchange="updateTestUnits()"><option value="all">すべて</option><option value="geography">地理</option><option value="history">歴史</option><option value="civics">公民</option></select></label><label class="field">単元<select id="testUnit"><option value="all">すべて</option>${[...new Set(filteredQs().map(q=>q.unit))].map(u=>`<option>${esc(u)}</option>`).join("")}</select></label><label class="field">難易度<select id="testDiff"><option value="auto">おまかせ</option><option value="basic">⭐ 基礎</option><option value="standard">⭐⭐ 標準</option><option value="advanced">⭐⭐⭐ 応用</option></select></label><label class="field">問題数<select id="testCount"><option>5</option><option selected>10</option><option>20</option><option>30</option><option>50</option><option>100</option></select></label><label class="field">制限時間<select id="testTime"><option value="0">なし</option><option value="300">5分</option><option value="600">10分</option><option value="900">15分</option><option value="1800">30分</option></select></label><label class="check"><input id="weakPriority" type="checkbox"> 苦手問題を優先する</label><div class="actions"><button class="btn" onclick="beginTest()">テスト開始</button></div><p class="muted">学期を選ぶと、その学期に割り当てられた問題だけから出題します。中間・期末の範囲は「範囲設定」で学校の範囲に合わせて変更できます。</p></div>`}
function updateTestUnits(){const cat=document.getElementById("testCat").value,units=[...new Set(filteredQs().filter(q=>cat==="all"||q.category===cat).map(q=>q.unit))];document.getElementById("testUnit").innerHTML='<option value="all">すべて</option>'+units.map(u=>`<option>${esc(u)}</option>`).join("")}
function applyPreset(){const t=document.getElementById("testType").value;if(t==="weak"){document.getElementById("weakPriority").checked=true;return}if(t==="mid"||t==="final"){document.getElementById("testCat").value="all";updateTestUnits();document.getElementById("weakPriority").checked=false}}
function beginTest(){const type=document.getElementById("testType").value,cat=document.getElementById("testCat").value,unit=document.getElementById("testUnit").value,diff=document.getElementById("testDiff").value,count=+document.getElementById("testCount").value,weak=document.getElementById("weakPriority").checked,limit=+document.getElementById("testTime").value;let qs=filteredQs().filter(q=>(cat==="all"||q.category===cat)&&(unit==="all"||q.unit===unit));if(type==="mid"||type==="final"){const scope=state.scopes[type];qs=filteredQs().filter(q=>scope.includes(q.unit))}if(type==="weak")qs=weakQs(filteredQs()).length?weakQs(filteredQs()):filteredQs();if(diff!=="auto")qs=qs.filter(q=>q.difficulty===diff);if(weak)qs.sort((a,b)=>weakness(b)-weakness(a));else qs.sort(()=>Math.random()-.5);qs=qs.slice(0,count);if(!qs.length){alert("条件に合う問題がありません。");return}test={type,qs,i:0,selected:null,score:0,started:Date.now(),limit,remaining:limit,results:[]};screen="testRun";render()}
function startTimer(){if(!test?.limit||timerId)return;timerId=setInterval(()=>{test.remaining--;const el=document.getElementById("timer");if(el)el.textContent=formatTime(test.remaining);if(test.remaining<=0){clearInterval(timerId);timerId=null;finishTest()}},1000)}
function formatTime(s){s=Math.max(0,s);return `${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`}
function testRunView(){if(!test)return "";const q=test.qs[test.i];if(!q)return resultView();return `<div class="card"><div class="section-title"><div class="muted">第${test.i+1}問 / ${test.qs.length}　<span class="tag">${catName(q.category)}</span><span class="tag">${esc(q.unit)}</span></div>${test.limit?`<span class="timer" id="timer">${formatTime(test.remaining)}</span>`:""}</div><div class="progress"><i style="width:${test.i/test.qs.length*100}%"></i></div><h2>${esc(q.q)}</h2><div id="choices">${q.choices.map((c,i)=>`<button class="choice" data-i="${i}"><span class="optionlabel">${String.fromCharCode(65+i)}</span>${esc(c)}</button>`).join("")}</div><div id="feedback"></div><div class="actions"><button class="btn secondary" id="nextBtn" disabled>次へ</button><button class="btn bad" onclick="finishTest()">ここで終了</button></div></div>`}
function bindTestRun(){document.querySelectorAll(".choice").forEach(b=>b.onclick=()=>{if(test.selected!==null)return;test.selected=+b.dataset.i;const q=test.qs[test.i],ok=test.selected===q.answer,s=statFor(q.id);s.attempts++;state.answers++;if(ok){s.correct++;s.streak++;state.correct++;test.score++}else{s.wrong++;s.streak=0}s.last=Date.now();test.results.push({id:q.id,ok});saveState();document.querySelectorAll(".choice").forEach(x=>{const i=+x.dataset.i;if(i===q.answer)x.classList.add("correct");if(i===test.selected&&!ok)x.classList.add("wrong")});document.getElementById("feedback").innerHTML=`<div class="notice"><b>${ok?"正解！":"不正解"}</b><p>正解：${esc(q.choices[q.answer])}</p><p>${esc(q.a)}</p></div>`;document.getElementById("nextBtn").disabled=false});document.getElementById("nextBtn").onclick=()=>{test.i++;test.selected=null;if(test.i>=test.qs.length)finishTest();else render()}}
function finishTest(){if(!test)return;clearInterval(timerId);timerId=null;if(test.i<test.qs.length&&test.selected===null&&test.qs[test.i]){test.i=test.qs.length}state.tests.unshift({date:new Date().toISOString(),score:test.score,total:test.qs.length,pct:Math.round(test.score/test.qs.length*100),type:test.type});state.tests=state.tests.slice(0,50);saveState();screen="result";render()}
function resultView(){const pct=Math.round(test.score/test.qs.length*100),wrong=test.results.filter(x=>!x.ok).map(x=>x.id);return `<div class="card center"><h2>テスト終了！</h2><div class="score">${pct}点</div><p>${test.qs.length}問中 <b>${test.score}問正解</b></p><div class="progress"><i style="width:${pct}%"></i></div><div class="actions"><button class="btn warn" onclick='startReview(${JSON.stringify(wrong)})'>間違いを復習</button><button class="btn" onclick="go('testSetup')">もう一度</button><button class="btn secondary" onclick="go('home')">ホーム</button></div></div>`}
function startReview(ids){const qs=ids.map(id=>QUESTIONS.find(q=>q.id===id)).filter(Boolean);if(qs.length)startFlash(qs);else go("home")}
function reviewView(){const wrong=[];Object.entries(state.stats).forEach(([id,s])=>{if(s.wrong>0)wrong.push(QUESTIONS.find(q=>q.id===id))});const qs=wrong.filter(Boolean).sort((a,b)=>weakness(b)-weakness(a)).slice(0,20);return `<div class="card"><h2>🔁 間違い復習</h2>${qs.length?qs.map(q=>`<div class="review-item"><b>${esc(q.q)}</b><div class="muted">${catName(q.category)} / ${esc(q.unit)} / 苦手度 ${weakness(q)}</div></div>`).join("")+`<div class="actions"><button class="btn" onclick='startReview(${JSON.stringify(qs.map(q=>q.id))})'>この問題を学習する</button></div>`:`<div class="empty">まだ間違えた問題はありません。</div>`}</div>`}
function statsView(){const units=unitStats(),rows=Object.entries(units).sort((a,b)=>b[1].weak-a[1].weak),acc=state.answers?Math.round(state.correct/state.answers*100):0;return `<div class="card"><h2>📊 学習成績 <span class="tag">問題バンク500問</span></h2><div class="statgrid"><div class="stat"><span class="muted">回答数</span><b>${state.answers}</b></div><div class="stat"><span class="muted">正解数</span><b>${state.correct}</b></div><div class="stat"><span class="muted">正答率</span><b>${acc}%</b></div><div class="stat"><span class="muted">苦手</span><b>${weakQs().length}</b></div></div><div class="actions"><button class="btn warn" onclick="go('review')">間違い復習</button><button class="btn secondary" onclick="exportData()">学習データを書き出す</button><label class="btn secondary" style="cursor:pointer">データを読み込む<input type="file" accept="application/json" hidden onchange="importData(event)"></label><button class="btn bad" onclick="resetData()">学習データをリセット</button></div></div><div class="card"><h3>単元別の理解度</h3>${rows.map(([u,v])=>{const p=v.attempts?Math.round(v.correct/v.attempts*100):0;return `<div class="unit-row"><span>${esc(u)}</span><div class="bar"><i style="width:${p}%"></i></div><b>${p}%</b></div>`}).join("")}</div><div class="card"><h3>テスト履歴</h3>${state.tests.length?`<table><tr><th>日時</th><th>種類</th><th>点数</th></tr>${state.tests.slice(0,20).map(t=>`<tr><td>${new Date(t.date).toLocaleString("ja-JP")}</td><td>${t.type==="mid"?"中間":t.type==="final"?"期末":t.type==="weak"?"苦手":t.type==="daily"?"今日の5問":"自由"}</td><td><b>${t.pct}点</b>（${t.score}/${t.total}）</td></tr>`).join("")}</table>`:`<p class='muted'>まだテスト履歴がありません。</p>`}</div>`}
function exportData(){const blob=new Blob([JSON.stringify({version:"0.7",exportedAt:new Date().toISOString(),questionCount:QUESTIONS.length,state},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="chugaku2_shakai_navi_data.json";a.click();URL.revokeObjectURL(a.href)}
function importData(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x.state)throw Error();state=normalize(x.state);saveState();alert("学習データを読み込みました。");render()}catch(_){alert("読み込みに失敗しました。正しいデータファイルを選択してください。")}};r.readAsText(f)}
function resetData(){if(confirm("学習記録をすべてリセットします。よろしいですか？")){state=structuredClone(defaultState);saveState();render()}}
function scopeView(){const units=[...new Set(QUESTIONS.map(q=>q.unit))];return `<div class="card"><h2>⚙️ テスト範囲設定</h2><p class="muted">学校の実際の中間・期末テスト範囲に合わせて設定できます。学期の標準割当も出題フィルターに使用します。</p><div class="scope-cols">${["mid","final"].map(k=>`<div><h3>${k==="mid"?"中間テスト":"期末テスト"}</h3>${units.map(u=>`<label class="check"><input type="checkbox" name="${k}" value="${esc(u)}" ${state.scopes[k].includes(u)?"checked":""}>${esc(u)}</label>`).join("")}</div>`).join("")}</div><div class="actions"><button class="btn" onclick="saveScopes()">保存する</button><button class="btn secondary" onclick="resetScopes()">初期設定に戻す</button></div></div>`}
function saveScopes(){for(const k of ["mid","final"])state.scopes[k]=[...document.querySelectorAll(`input[name="${k}"]:checked`)].map(x=>x.value);saveState();alert("テスト範囲を保存しました。");render()}
function resetScopes(){state.scopes=JSON.parse(JSON.stringify(DEFAULT_SCOPES));saveState();render()}
render();
